// Üretilen dosya: tool/ozgun/uret.py. Coğrafya · Avrupa ve Rusya bölgesel coğrafyası (orta).
const ozGeography10Orta = <(String, String, List<String>, String)>[
  ('Geleneksel tanımda Avrupa ile Asya arasındaki sınır, Ural Dağları\'nın güney ucundan Hazar Denizi\'ne kadar hangi akarsuyu izler?', 'Ural Nehri', ['Volga Nehri', 'Don Nehri', 'Peçora Nehri'], 'Yaygın kabulde kıta sınırı Ural Dağları\'ndan sonra Ural Nehri boyunca Hazar Denizi\'ne iner. Volga ve Don tümüyle Avrupa yakasında akar.'),
  ('Avrupa anakarasının en batı noktasında durmak isteyen bir gezgin Lizbon\'dan batıya, Sintra Dağları\'nın okyanusa indiği kıyıya gidiyor. Gezginin varacağı burun hangisidir?', 'Roca Burnu', ['Finisterre Burnu', 'Tarifa Burnu', 'São Vicente Burnu'], 'Portekiz\'deki Roca Burnu (Cabo da Roca) Avrupa anakarasının en batı noktasıdır. Tarifa en güney uçtur.'),
  ('Avrupa anakarasının en güney noktası olan ve Cebelitarık Boğazı\'na bakan burun hangi ülkededir?', 'İspanya', ['Yunanistan', 'İtalya', 'Portekiz'], 'Avrupa anakarasının en güney ucu İspanya\'daki Tarifa Burnu\'dur. Yunanistan\'daki Matapan ise Balkan Yarımadası\'nın güney ucudur ama daha kuzeydedir.'),
  ('Rusya\'nın yüzölçümü ile nüfusunun Avrupa ve Asya kesimleri arasındaki dağılımı için hangisi doğrudur?', 'Toprağın çoğu Asya\'da, nüfusun çoğu Avrupa\'dadır', ['Toprağın ve nüfusun çoğu Asya\'dadır', 'Toprağın çoğu Avrupa\'da, nüfusun çoğu Asya\'dadır', 'Toprak ve nüfus iki kıtaya eşit bölünmüştür'], 'Rusya topraklarının yaklaşık dörtte üçü Ural\'ın doğusundaki Asya kesimindedir. Buna karşın halkın yaklaşık dörtte üçü daha ılıman Avrupa kesiminde yaşar.'),
  ('İsveç, Finlandiya ve Kola Yarımadası\'nın temelini oluşturan, Prekambriyen yaşlı kayaçlardan oluşmuş, sabit ve aşınmış yaşlı kütle hangisidir?', 'Baltık Kalkanı', ['Rus Platformu', 'Hersinyen Kuşağı', 'Pannonya Havzası'], 'Fennoskandiya da denilen Baltık Kalkanı, Avrupa\'nın en yaşlı kayaçlarını barındıran sabit bir kalkandır. Buzullar bu kalkanı aşındırıp göl çukurları açmıştır.'),
  ('Fransa\'daki Massif Central, Almanya\'daki Kara Orman ve Çekya\'daki Bohemya Masifi\'nin ortak özelliği hangisidir?', 'Yaşlı bir orojenezle oluşup aşınarak alçalmış kütleler olmaları', ['Genç volkanik konilerden oluşan yüksek sıradağlar olmaları', 'Buzul birikintileriyle oluşmuş moren tepeleri olmaları', 'Alp kıvrılmasıyla yükselmiş genç ve sarp sıradağlar olmaları'], 'Bu kütleler Paleozoyik\'teki Hersinyen (Varisken) orojenezinde oluşmuş, uzun süre aşınarak yuvarlak hatlı orta yükseklikteki masiflere dönüşmüştür.'),
  ('Innsbruck\'tan Verona\'ya karayoluyla mal taşıyan bir tır, Alpler\'i Avusturya-İtalya sınırındaki hangi geçitten aşar?', 'Brenner Geçidi', ['Simplon Geçidi', 'Saint-Bernard Geçidi', 'Gotthard Geçidi'], 'Brenner Geçidi Avusturya\'nın Tirol bölgesini İtalya\'nın Güney Tirol bölgesine bağlar. Simplon ve Gotthard İsviçre\'de, Büyük Saint-Bernard ise İsviçre-İtalya arasındadır.'),
  ('Avusturya\'nın en yüksek dağı olan ve eteğinde Pasterze Buzulu\'nun uzandığı zirve hangisidir?', 'Grossglockner', ['Zugspitze', 'Triglav', 'Ortler'], 'Yaklaşık 3.798 m olan Grossglockner Avusturya\'nın en yüksek zirvesidir. Triglav Slovenya\'nın, Zugspitze Almanya\'nın en yüksek zirvesidir.'),
  ('Fransa\'daki Chamonix ile İtalya\'daki Courmayeur\'ü bağlayan karayolu tüneli hangi dağın altından geçer?', 'Mont Blanc', ['Matterhorn', 'Monte Rosa', 'Jungfrau'], 'Mont Blanc Tüneli, Alpler\'in en yüksek zirvesinin altından geçerek Fransa\'nın Chamonix vadisini İtalya\'nın Aosta vadisindeki Courmayeur\'e bağlar.'),
  ('Pireneler\'in en yüksek zirvesi olan Aneto hangi ülkenin topraklarındadır?', 'İspanya', ['Fransa', 'Andorra', 'Portekiz'], 'Yaklaşık 3.404 m yüksekliğindeki Aneto, Pireneler\'in İspanya\'daki Aragon kesiminde yer alır.'),
  ('Fransa\'daki Vosges Dağları ile Almanya\'daki Kara Orman arasında uzanan geniş ve düz Yukarı Ren Ovası nasıl oluşmuştur?', 'İki fay arasında yer kabuğunun çökmesiyle', ['Bir buzul dilinin vadiyi genişletmesiyle', 'Eski bir iç denizin kuruyup çekilmesiyle', 'Volkanik küllerin çukuru doldurmasıyla'], 'Yukarı Ren Ovası tipik bir grabendir: iki yandaki Vosges ve Kara Orman horst gibi yükselirken aradaki blok çökmüş, Ren de bu çöküntüyü izlemiştir.'),
  ('Fransa\'nın Auvergne bölgesinde Puy de Dôme\'un da içinde bulunduğu, sıra hâlinde dizilmiş çok sayıda koni biçimli tepe neyin kalıntısıdır?', 'Sönmüş volkanların', ['Buzul morenlerinin', 'Karstik kuleleri', 'Kum tepelerinin'], 'Massif Central\'daki Chaîne des Puys, birkaç bin yıl önce etkinliği sona ermiş volkan konilerinden oluşan bir sıradır.'),
  ('Yer bilimindeki Jura dönemi adını nereden almıştır?', 'Fransa ile İsviçre arasındaki dağ sırasından', ['Almanya\'da bulunan bir antik Roma kentinden', 'İngiltere\'deki fosilli bir kıyı kayalığından', 'Bu dönemi ilk tanımlayan bilim insanının adından'], 'Jura dönemi, kireçtaşı katmanları ilk kez ayrıntılı incelenen Fransa-İsviçre sınırındaki Jura Dağları\'ndan adını alır.'),
  ('Almanya ile Çekya arasında sınır oluşturan ve adını yüzyıllar boyunca işletilen gümüş ve kalay yataklarından alan dağlar hangisidir?', 'Cevher Dağları', ['Harz Dağları', 'Sudet Dağları', 'Ardenler'], 'Almancası Erzgebirge olan Cevher Dağları, Saksonya ile Bohemya arasında uzanır. Adı \'maden cevheri dağları\' anlamına gelir.'),
  ('Karpat Dağları\'nın en yüksek kesimi olan ve Slovakya ile Polonya arasında uzanan dağ grubu hangisidir?', 'Tatra Dağları', ['Sudet Dağları', 'Transilvanya Alpleri', 'Bohemya Ormanı'], 'Yüksek Tatra, Karpatlar\'ın en yüksek kesimidir; zirvesi Gerlachovský štít yaklaşık 2.655 m ile Slovakya\'dadır.'),
  ('Belçika\'nın güneydoğusu, Lüksemburg\'un kuzeyi ve Fransa\'nın kuzeydoğusuna yayılan ormanlık yaşlı plato hangisidir?', 'Ardenler', ['Vosges', 'Eifel', 'Jura'], 'Ardenler, Hersinyen kökenli aşınmış bir platodur ve Belçika, Lüksemburg ile Fransa\'ya yayılır.'),
  ('Kuzey İngiltere\'yi boydan boya kat ettiği için \'İngiltere\'nin omurgası\' diye anılan alçak dağ sırası hangisidir?', 'Penninler', ['Cheviot Tepeleri', 'Cotswold Tepeleri', 'Cambrian Dağları'], 'Penninler kuzeyde İskoçya sınırına yakın yerlerden Orta İngiltere\'ye kadar uzanır ve batı ile doğu İngiltere\'yi birbirinden ayırır.'),
  ('İngiltere\'nin en yüksek zirvesi Scafell Pike, buzul gölleriyle tanınan hangi bölgededir?', 'Göller Bölgesi', ['Peak District', 'Yorkshire Dales', 'Dartmoor'], 'Scafell Pike yaklaşık 978 m\'dir ve kuzeybatı İngiltere\'deki Cumbria\'da, Göller Bölgesi\'nde yer alır.'),
  ('Galler\'in en yüksek dağı olan ve Galce adı Yr Wyddfa olan zirve hangisidir?', 'Snowdon', ['Ben Macdui', 'Cadair Idris', 'Slieve Donard'], 'Snowdon (Yr Wyddfa) yaklaşık 1.085 m ile Galler\'in en yüksek noktasıdır ve kuzey Galler\'deki Snowdonia\'da bulunur.'),
  ('İsveç\'in en yüksek dağı olan ve kutup dairesinin kuzeyinde, Laponya\'da yükselen zirve hangisidir?', 'Kebnekaise', ['Galdhøpiggen', 'Halti', 'Snøhetta'], 'Kebnekaise İsveç\'in en yüksek dağıdır ve İsveç Laponyası\'nda, Kiruna yakınlarında bulunur.'),
  ('İzlanda\'daki Þingvellir Ulusal Parkı\'nda görülen derin yarıkların jeolojik açıklaması nedir?', 'Kuzey Amerika ve Avrasya levhalarının ayrılması', ['Afrika ve Avrasya levhalarının birbirine çarpması', 'Bir buzul örtüsünün erimesiyle kabuğun çökmesi', 'Okyanus tabanının bir dalma zonunda batması'], 'İzlanda Orta Atlas Sırtı üzerinde yer alır. Þingvellir\'de iki levhanın ayrılması yüzeyde gözle görülebilen fay yarıkları oluşturur.'),
  ('Dünyada sıcak su fışkıran kaynakları anlatan \'gayzer\' sözcüğü nereden gelir?', 'İzlanda\'daki Geysir adlı kaynaktan', ['Yeni Zelanda\'daki bir Maori sözcüğünden', 'Rusya\'daki Kamçatka vadisinin adından', 'ABD\'deki bir milli parkın kurucusundan'], 'Haukadalur vadisindeki Büyük Geysir, Avrupalılarca bilinen ilk gayzerdir; İzlandaca \'fışkırmak\' anlamındaki adı bu tür kaynakların genel adı olmuştur.'),
  ('İzlanda\'da evlerin büyük bölümünün kömür ya da doğal gaz yerine yer altındaki sıcak suyla ısıtılabilmesini sağlayan koşul hangisidir?', 'Ülkenin bir okyanus sırtı ve sıcak nokta üzerinde olması', ['Ülkenin Golf Akıntısı\'nca çevrelenmiş olması', 'Ülkede büyük linyit yataklarının bulunması', 'Ülkenin kutup dairesinin güneyinde kalması'], 'İzlanda hem Orta Atlas Sırtı\'nda hem de bir manto sıcak noktası üzerindedir. Bu nedenle yer altı sıcaklığı yüksektir ve jeotermal su bolca kullanılır.'),
  ('Yaklaşık iki bin yıldır neredeyse kesintisiz, kısa aralıklı küçük patlamalar yaptığı için \'Akdeniz\'in deniz feneri\' diye anılan volkan adası hangisidir?', 'Stromboli', ['Santorini', 'Vulcano', 'Sicilya'], 'Tiren Denizi\'ndeki Eolie (Lipari) Adaları\'ndan Stromboli, sürekli etkinliği nedeniyle gece denizcilere ışık saçar; bu tür püskürmeye de \'Stromboli tipi\' denir.'),
  ('Ege\'deki Santorini Adası\'nın hilal biçimini almasının ve ortasında derin bir deniz çanağı bulunmasının nedeni nedir?', 'Püskürmeden sonra volkanın çöküp kaldera oluşturması', ['Buzul Çağı\'nda buzulların adanın ortasını oyması', 'Bir mercan halkasının zamanla denizle dolması', 'Fay hatları boyunca adanın ikiye ayrılıp açılması'], 'Tunç Çağı\'ndaki büyük Minos (Thera) püskürmesinden sonra magma odasının boşalmasıyla volkanın tepesi çökmüş ve deniz suyunun doldurduğu bir kaldera oluşmuştur.'),
  ('\'Volkan\' sözcüğünün kökeniyle ilişkilendirilen ve Sicilya\'nın kuzeyindeki Eolie Takımadası\'nda bulunan ada hangisidir?', 'Vulcano', ['Lipari', 'Malta', 'Capri'], 'Romalılar Vulcano Adası\'nı ateş ve demircilik tanrısı Vulcanus\'un ocağı sayardı. Sözcük bu inanış yoluyla dünyadaki bütün yanardağların genel adı olmuştur.'),
  ('Fransa\'nın güneybatısında, Bordeaux çevresinde uzanan ve Garonne ile kollarının suladığı alçak havza hangisidir?', 'Akitanya Havzası', ['Paris Havzası', 'Ron Vadisi', 'Alsas Ovası'], 'Akitanya Havzası Pireneler ile Massif Central arasında Atlas Okyanusu\'na açılan bir tortul havzadır. Garonne ve Dordogne bu havzayı sular.'),
  ('Doğu Avrupa Ovası için aşağıdakilerden hangisi doğrudur?', 'Avrupa\'nın en geniş düzlüğü olup yükseltisi azdır', ['Yüksek dağlarla çevrili kapalı bir iç havzadır', 'Genç volkanik platolardan oluşmuş engebeli bir alandır', 'Akdeniz kıyısına kadar uzanan dar bir kıyı ovasıdır'], 'Rus Ovası da denilen Doğu Avrupa Ovası, Baltık\'tan Ural\'a kadar uzanan, ortalama yükseltisi yaklaşık 170 m olan çok geniş bir düzlüktür.'),
  ('Romanya\'da Güney Karpatlar ile Tuna Nehri arasında uzanan ve ülkenin başkentini de içine alan geniş ova hangisidir?', 'Eflak Ovası', ['Pannonya Ovası', 'Dobruca Platosu', 'Moldova Platosu'], 'Eflak (Valahya) Ovası, Tuna\'nın kuzeyindeki verimli alüvyal düzlüktür. Bükreş bu ovada yer alır.'),
  ('Koblenz\'deki \'Alman Köşesi\' anıtında duran bir turist, Ren\'e soldan katılan ve Lüksemburg sınırından gelen bağlık vadili akarsuya bakıyor. Bu akarsu hangisidir?', 'Mosel', ['Main', 'Neckar', 'Ruhr'], 'Mosel Fransa\'daki Vosges\'ten doğar, Lüksemburg sınırını izler ve Koblenz\'deki \'Deutsches Eck\' denen burunda Ren\'e katılır.'),
  ('Ruhr bölgesinin kömür ve çeliğini Ren üzerinden Rotterdam\'a taşımak isteyen bir şirket, Ruhr ile Ren\'in birleştiği yerdeki büyük iç limanı kullanacaktır. Bu liman hangi kenttedir?', 'Duisburg', ['Düsseldorf', 'Dortmund', 'Essen'], 'Duisburg, Ren ile Ruhr\'un birleştiği yerde kurulmuştur; liman tesisleri Ruhr sanayi bölgesinin Ren üzerinden denize bağlanmasını sağlar.'),
  ('Orta Ren\'in dar ve kayalık boğaz kesiminde, efsaneye göre şarkısıyla gemicileri kayalara sürükleyen bir kızla anılan ünlü kaya hangisidir?', 'Lorelei', ['Bastei', 'Externsteine', 'Drachenfels'], 'Sankt Goarshausen yakınlarındaki Lorelei, Ren\'in en dar ve tehlikeli yerlerinden birinde yükselir. Burada akıntının güçlü olması efsanenin doğmasına yol açmıştır.'),
  ('Bir bisikletli Ren boyunca pedal çevirirken aynı gün içinde İsviçre, Fransa ve Almanya sınırlarının buluştuğu noktaya ulaşıyor. Bisikletli hangi kenttedir?', 'Basel', ['Strazburg', 'Konstanz', 'Mulhouse'], 'Basel, Ren\'in batıya yaptığı dirsekten sonra kuzeye döndüğü yerde, üç ülkenin sınırlarının kesiştiği noktadadır ve İsviçre\'nin Ren üzerindeki tek limanına sahiptir.'),
  ('Tuna Nehri\'nin Güney Karpatlar ile Sırp dağları arasındaki dar boğazından geçtiği ve büyük bir hidroelektrik barajının bulunduğu yer hangisidir?', 'Demir Kapı', ['Wachau Vadisi', 'Tuna Dirseği', 'Sulina Ağzı'], 'Demir Kapı, Tuna\'nın Sırbistan ile Romanya sınırını oluşturduğu dar ve derin boğazdır. 1970\'lerde iki ülkenin ortak kurduğu barajlar akarsuyu buradan enerji üretiminde kullanır.'),
  ('Berlin\'den doğuya trenle giden bir yolcu Frankfurt (Oder) kentinde Polonya\'ya geçiyor. Bu yolcunun aştığı sınırın büyük bölümünü hangi iki akarsu çizer?', 'Oder ve Neisse', ['Elbe ve Saale', 'Vistül ve Bug', 'Ren ve Mosel'], '1945\'ten sonra çizilen Oder-Neisse hattı, Almanya ile Polonya arasındaki bugünkü sınırın temelidir.'),
  ('Bordeaux\'dan teknesiyle denize açılan bir denizci, geniş Gironde Halici\'nden geçerek Atlas Okyanusu\'na çıkıyor. Bu halici oluşturan iki akarsu hangileridir?', 'Garonne ve Dordogne', ['Loire ve Cher', 'Sen ve Marne', 'Ron ve Saône'], 'Garonne ile Dordogne, Bordeaux\'nun kuzeyinde birleşerek Gironde Haliçi\'ni oluşturur. Bu halicin çevresi dünyaca ünlü bağ alanlarıdır.'),
  ('Lyon\'un tarihî yarımadasının güney ucunda duran bir turist iki akarsuyun birleştiğini görüyor. Bunlardan biri Ron ise diğeri hangisidir?', 'Saône', ['Isère', 'Durance', 'Doubs'], 'Lyon, Ron ile Saône\'un birleştiği yerde kurulmuştur. Birleşme noktası kentin tarihî yarımadasının güney ucundadır.'),
  ('Flamingo gözlemek ve pirinç tarlalarını görmek isteyen bir doğa fotoğrafçısı Arles\'ın güneyine, Ron\'un denize ulaştığı sulak alanlara gidiyor. Fotoğrafçının gittiği bölge hangisidir?', 'Camargue', ['Provence', 'Landes', 'Languedoc'], 'Ron iki kola ayrılarak Arles\'ın güneyinde Camargue deltasını oluşturur. Lagünleri ve sulak alanları önemli bir kuş yaşam alanıdır.'),
  ('İber Yarımadası\'nın en uzun akarsuyu olan ve Toledo\'dan geçip Lizbon\'da Atlas Okyanusu\'na açılan nehir hangisidir?', 'Tajo (Tejo)', ['Ebro', 'Duero (Douro)', 'Guadiana'], 'Tajo, İspanya\'nın ortasından doğar, Toledo\'yu çevreleyerek akar ve Portekiz\'de Tejo adını alarak Lizbon önünde geniş bir haliçle okyanusa dökülür.'),
  ('Keşifler çağında Amerika\'dan dönen kalyonlar Atlas\'tan bir akarsuya girip iç kesimdeki Sevilla limanına kadar çıkabiliyordu. Bu gemilerin izlediği akarsu hangisidir?', 'Guadalquivir', ['Guadiana', 'Ebro', 'Guadalete'], 'Endülüs\'teki Guadalquivir, Atlas Okyanusu\'na döküldüğü yerden Sevilla\'ya kadar gemi ulaşımına elverişlidir. Bu özellik Sevilla\'yı keşifler çağında önemli bir liman yapmıştır.'),
  ('Porto\'da Dom Luís Köprüsü\'nün üzerinden geçen bir turist, altından akan ve teraslı bağlar arasından gelen akarsuyu izliyor. Bu akarsu hangisidir?', 'Douro', ['Minho', 'Mondego', 'Tejo'], 'İspanya\'da Duero adını taşıyan Douro, Porto\'da okyanusa dökülür. Yukarı Douro vadisi, ünlü Porto şarabının üretildiği teraslı bağlarıyla UNESCO listesindedir.'),
  ('Birleşik Krallık\'ın en uzun akarsuyu olan ve halicinde dünyanın en yüksek gelgit genliklerinden biri görülen nehir hangisidir?', 'Severn', ['Thames', 'Trent', 'Ouse'], 'Severn, Galler\'den doğup İngiltere\'den geçerek Bristol Kanalı\'na dökülür. Huni biçimli halicinde gelgit genliği 14 metreyi aşabilir.'),
  ('Bir kano tutkunu Fransa\'nın Lorraine bölgesinden başlayıp Belçika\'da Liège\'den, Hollanda\'da Maastricht\'ten geçen bir akarsuyu izliyor. Kanocunun izlediği akarsu hangisidir?', 'Meuse (Maas)', ['Schelde (Escaut)', 'Mosel', 'Sambre'], 'Meuse, Fransa\'nın Lorraine bölgesinden doğar; Belçika ve Hollanda\'yı geçerek Ren-Meuse deltası üzerinden Kuzey Denizi\'ne ulaşır.'),
  ('Romanya\'nın Iași kentinden doğuya giden bir sürücü, kısa süre sonra bir akarsuyu geçerek Moldova\'ya giriyor. Sürücünün geçtiği sınır akarsuyu hangisidir?', 'Prut', ['Dinyester', 'Siret', 'Olt'], 'Prut, Ukrayna Karpatları\'ndan doğar, Romanya ile Moldova arasında sınır çizerek güneyde Tuna\'ya katılır.'),
  ('Rusya\'nın kuzeyinde Arhangelsk kenti yakınında Beyaz Deniz\'e dökülen akarsu hangisidir?', 'Kuzey Dvina', ['Peçora', 'Mezen', 'Onega Nehri'], 'Kuzey Dvina, Arhangelsk\'in kıyısından geçerek Beyaz Deniz\'in Dvina Körfezi\'ne dökülür. Bu yol 16. yüzyıldan beri Rusya\'nın kuzey ticaret kapısı olmuştur.'),
  ('İskoçya\'daki Loch Lomond yüzey alanı bakımından Loch Ness\'ten büyük olduğu hâlde Loch Ness daha fazla tatlı su barındırır. Bunun nedeni nedir?', 'Loch Ness\'in çok daha derin olması', ['Loch Ness\'in denize bağlı olması', 'Loch Lomond\'un yazın tümüyle kuruması', 'Loch Ness\'in birden çok gölden oluşması'], 'Su hacmi alan ile derinliğe bağlıdır. Great Glen fay oluğundaki Loch Ness 200 metreyi aşan derinliğiyle, daha geniş ama sığ olan Loch Lomond\'dan fazla su tutar.'),
  ('Bir turist göl ortasındaki adacıkta bulunan kiliseye kayıkla gitmek için Julian Alpleri\'nin eteğindeki Bled Gölü\'ne gidiyor. Turist hangi ülkededir?', 'Slovenya', ['Avusturya', 'Hırvatistan', 'İsviçre'], 'Bled Gölü Slovenya\'nın kuzeybatısındadır. Göldeki tek doğal ada ve üzerindeki kilise ülkenin en tanınmış manzarasıdır.'),
  ('Hırvatistan\'daki Plitvice Gölleri\'nin birbirine şelalelerle bağlanan basamaklar hâlinde dizilmesini sağlayan doğal setler neyden oluşur?', 'Kalsiyum karbonatın çökelmesiyle oluşan travertenden', ['Buzulların bıraktığı moren yığınlarından', 'Volkanik lavın soğumasıyla oluşan bazalttan', 'Kunduzların yaptığı ağaç barajlardan'], 'Karstik bölgeden gelen kirece doymuş sular yosun ve bitkiler üzerinde kalsiyum karbonat bırakır. Biriken traverten setleri gölleri basamak basamak ayırır.'),
  ('Polonya\'nın kuzeydoğusunda, buzulların bıraktığı yüzlerce gölle kaplı ve \'bin göller ülkesi\' diye anılan bölge hangisidir?', 'Mazurya', ['Silezya', 'Pomeranya', 'Galiçya'], 'Mazurya, son buzullaşmanın moren ve çanaklarında oluşmuş binlerce gölüyle Polonya\'nın en önemli göl bölgesidir.'),
  ('Cenova Körfezi\'nin de içinde bulunduğu, İtalya\'nın kuzeybatı kıyısı ile Korsika arasındaki deniz hangisidir?', 'Ligurya Denizi', ['Tiren Denizi', 'Adriyatik Denizi', 'Balear Denizi'], 'Ligurya Denizi, İtalyan Rivierası\'nın önünde uzanır; kuzeyindeki Cenova Körfezi, Akdeniz\'in önemli liman alanlarından biridir.'),
  ('Fransa\'nın Akdeniz kıyısında, Pireneler\'den Ron deltasına kadar uzanan geniş körfezin adı nedir?', 'Lion Körfezi', ['Cenova Körfezi', 'Biskay Körfezi', 'Valensiya Körfezi'], 'Lion Körfezi, Fransa\'nın Languedoc ve Roussillon kıyılarının önünde yer alır. Mistral ve Tramontane rüzgârları bu körfezi sık sık fırtınalı yapar.'),
  ('Ortalama derinliği yalnızca birkaç metre olan ve dünyanın en sığ denizi sayılan, Kırım\'ın kuzeydoğusundaki deniz hangisidir?', 'Azak Denizi', ['Marmara Denizi', 'Baltık Denizi', 'Beyaz Deniz'], 'Azak Denizi\'nin ortalama derinliği yaklaşık 7 m, en derin yeri ise 15 m dolayındadır. Don ve Kuban akarsularının tatlı suyu nedeniyle tuzluluğu da düşüktür.'),
  ('Norveç ile Rusya\'nın kuzey kıyılarını yıkayan Barents Denizi adını kimden alır?', 'Hollandalı denizci Willem Barentsz\'den', ['Rus Çarı Büyük Petro\'dan', 'Norveçli kâşif Roald Amundsen\'den', 'Danimarkalı Vitus Bering\'den'], '16. yüzyıl sonunda Asya\'ya kuzeydoğudan geçit arayan Willem Barentsz bu denizi keşfetmiş ve Novaya Zemlya\'da kışlamıştır.'),
  ('Aşağıdaki Baltık kıyısı kentlerinden hangisi Fin Körfezi\'nde değil, kendi adını taşıyan başka bir körfezin kıyısında yer alır?', 'Riga', ['Helsinki', 'Tallinn', 'St. Petersburg'], 'Helsinki, Tallinn ve St. Petersburg Fin Körfezi kıyısındadır. Letonya\'nın başkenti Riga ise Daugava\'nın ağzında, Riga Körfezi\'nin güney ucundadır.'),
  ('Hollanda, Almanya ve Danimarka kıyıları boyunca gelgitle günde iki kez su altında kalıp açığa çıkan geniş çamur düzlükleriyle UNESCO listesindeki deniz alanı hangisidir?', 'Wadden Denizi', ['Zuiderzee', 'Kattegat', 'Dollart Körfezi'], 'Wadden Denizi, Frizya Adaları\'nın gerisinde kalan sığ bir gelgit alanıdır. Gelgit düzlükleri kuş göçleri için dünyanın en önemli duraklarından biridir.'),
  ('Taş kule biçimindeki Tunç Çağı yapıları \'nuraghe\'lerle tanınan ve Akdeniz\'in ikinci büyük adası olan İtalyan adası hangisidir?', 'Sardinya', ['Sicilya', 'Korsika', 'Kıbrıs'], 'Sardinya, Sicilya\'dan sonra Akdeniz\'in ikinci büyük adasıdır. Adada binlerce nuraghe kalıntısı bulunur.'),
  ('Ege\'de Delos Adası\'nın çevresinde halka biçiminde dizildiği için adını \'çember\' anlamındaki bir sözcükten alan Yunan takımadası hangisidir?', 'Kiklad Adaları', ['Sporad Adaları', 'İyon Adaları', 'Onikiadalar'], 'Kiklad Adaları (Kykládes) antik dönemde kutsal Delos\'u çevreleyen bir halka olarak görülmüştür. Santorini, Mikonos ve Naksos bu takımadadadır.'),
  ('Büyük Britanya\'nın en kuzeyindeki takımada olan ve Norveç\'e İskoçya anakarasından daha yakın sayılabilecek konumdaki adalar hangisidir?', 'Shetland Adaları', ['Orkney Adaları', 'Hebrid Adaları', 'Faroe Adaları'], 'Shetland, İskoçya\'nın kuzeydoğusunda, Orkney\'nin de kuzeyindedir. Uzun süre İskandinav yönetiminde kalmış, 15. yüzyılda İskoçya\'ya geçmiştir.'),
  ('İskoçya\'nın batı kıyısı açığında, Lewis ve Skye adalarını da içeren takımada hangisidir?', 'Hebrid Adaları', ['Shetland Adaları', 'Orkney Adaları', 'Manş Adaları'], 'Hebridler İç ve Dış Hebridler olarak ikiye ayrılır. Skye İç, Lewis ve Harris ise Dış Hebridler\'dedir.'),
  ('Hansa döneminden kalma Visby surlarını görmek isteyen bir gezgin Stockholm\'ün güneyindeki Nynäshamn\'dan feribota biniyor. Gezginin gideceği ada hangisidir?', 'Gotland', ['Öland', 'Bornholm', 'Saaremaa'], 'Gotland, İsveç\'in en büyük adasıdır. Hansa döneminin ticaret kenti Visby, surlarıyla UNESCO listesindedir.'),
  ('Turku\'dan Stockholm\'e feribotla giden bir yolcu, yolun ortasında halkının İsveççe konuştuğu ama Finlandiya\'ya bağlı özerk adalarda mola veriyor. Bu adalar hangisidir?', 'Åland Adaları', ['Gotland Adası', 'Hiiumaa Adası', 'Lofoten Adaları'], 'Åland Adaları, Bothnia Körfezi\'nin girişinde yer alır. 1921\'de Milletler Cemiyeti kararıyla Finlandiya\'ya bırakılmış, İsveççe konuşan özerk ve silahsız bir bölge olmuştur.'),
  ('Kutup dairesinin kuzeyinde, denizden dik yükselen dağlar arasındaki balıkçı köylerinde kurutulmuş morina üretimini görmek isteyen bir turist Bodø\'dan feribota biniyor. Gideceği takımada hangisidir?', 'Lofoten Adaları', ['Faroe Adaları', 'Shetland Adaları', 'Åland Adaları'], 'Lofoten Adaları kuzey Norveç\'tedir. Golf Akıntısı\'nın ılıttığı sularında yüzyıllardır kurutulmuş morina üretilir.'),
  ('Çizmeye benzetilen İtalya Yarımadası\'nda \'burun\' kısmını oluşturan güney bölgesi hangisidir?', 'Kalabriya', ['Apulya', 'Basilikata', 'Kampanya'], 'İtalya\'nın güneybatı ucundaki Kalabriya çizmenin burnu, güneydoğudaki Apulya\'nın Salento kesimi ise topuğu sayılır.'),
  ('Kuzey Yunanistan\'da Ege\'ye üç parmak gibi uzanan ve en doğudaki kolunda manastırlarıyla ünlü Aynaroz\'un bulunduğu yarımada hangisidir?', 'Halkidiki', ['Mora', 'Atika', 'Magnisia'], 'Halkidiki\'nin üç kolu Kassandra, Sithonia ve Aynaroz\'dur (Athos). Aynaroz, Ortodoks keşişlerin yönettiği özerk bir manastır bölgesidir.'),
  ('Büyük Britanya\'nın güneybatı ucundaki yarımadanın en batı noktası olarak tanınan burun hangisidir?', 'Land\'s End', ['Lizard Point', 'John o\' Groats', 'Dover'], 'Land\'s End, Cornwall\'un batı ucundadır. Ada boyunca \'Land\'s End\'den John o\' Groats\'a\' yolculuğu ünlüdür; John o\' Groats İskoçya\'nın kuzeydoğusundadır.'),
  ('Kutup dairesinin kuzeyindeki Murmansk limanının kışın da buz tutmamasının nedeni nedir?', 'Golf Akıntısı\'nın devamı olan ılık suların kıyıya ulaşması', ['Kola Yarımadası\'nın sıcak su kaynaklarıyla çevrili olması', 'Barents Denizi\'nin tuzluluğunun okyanuslardan çok yüksek olması', 'Kentin rüzgârlardan korunan derin ve kapalı bir körfezde olması'], 'Kuzey Atlantik Akıntısı\'nın bir kolu Norveç kıyısını izleyerek Barents Denizi\'ne ulaşır. Bu ılık su, Murmansk\'ı yıl boyu açık kalan bir liman yapar.'),
  ('Benzer enlemlerdeki Londra ile Moskova karşılaştırıldığında Moskova\'da kış ve yaz sıcaklıkları arasındaki farkın çok daha büyük olmasının temel nedeni nedir?', 'Okyanusun ılımanlaştırıcı etkisinden uzak olması', ['Çok daha yüksek bir plato üzerinde kurulmuş olması', 'Ekvatora Londra\'dan çok daha yakın bir enlemde olması', 'Akdeniz\'den gelen sıcak hava kütlelerine açık olması'], 'Avrupa\'da batıdan doğuya gidildikçe Atlas Okyanusu\'nun etkisi azalır ve karasallık artar. Bu yüzden Moskova\'nın kışları çok soğuk, yazları ise görece sıcaktır.'),
  ('İskandinav Dağları\'nın doğusunda kalan İsveç\'in doğu kesimlerinin, aynı enlemdeki batı Norveç kıyılarına göre çok daha az yağış almasının nedeni nedir?', 'Dağların doğusunun yağış gölgesinde kalması', ['Doğu kesimlerin deniz düzeyinin altında olması', 'İsveç\'in Golf Akıntısı\'nca doğrudan ısıtılması', 'Doğu kesimlerde sürekli yüksek basınç bulunması'], 'Batı rüzgârları nemini Norveç tarafındaki yamaçlarda bırakır. Dağı aşıp inen hava kuru olduğundan İsveç\'in doğusu görece kurak kalır.'),
  ('İspanya\'nın iç kesimindeki Meseta\'da kışların soğuk, yazların çok sıcak ve kurak geçmesi bu yöre için hangisini gösterir?', 'Çevresindeki dağlar yüzünden karasallığın artması', ['Kıyıya yakınlık nedeniyle iklimin belirgin biçimde ılımanlaşması', 'Golf Akıntısı\'nın platonun iklimini doğrudan etkilemesi', 'Yöreye yaz ve kış boyunca muson yağışları düşmesi'], 'Meseta yüksek bir platodur ve kıyıya paralel dağlarla çevrilidir. Denizin etkisi içeri sokulamadığından Madrid çevresinde karasal özellikler belirgindir.'),
  ('1953\'teki büyük fırtına taşkınından sonra Hollanda\'nın güneybatısında haliçleri barajlar ve hareketli kapaklarla kapatmak için uygulanan büyük proje hangisidir?', 'Delta Planı', ['Zuiderzee Projesi', 'Ren-Main Kanalı', 'Europoort Projesi'], 'Delta Planı, Zeeland ve Güney Hollanda\'daki haliçleri kapatan baraj ve setlerden oluşur. Oosterschelde\'deki hareketli bariyer bu planın en bilinen parçasıdır.'),
  ('Hollanda\'nın Kinderdijk köyündeki 18. yüzyıl yel değirmenleri asıl olarak hangi amaçla yapılmıştır?', 'Polderlerdeki fazla suyu kanallara pompalamak', ['Tahıl öğütüp çevredeki kentlere un sağlamak', 'Kereste kesip tersanelerdeki gemi yapımına destek olmak', 'Tekstil atölyelerindeki tezgâhlara enerji sağlamak'], 'Deniz düzeyinin altındaki polderlerde su sürekli birikir. Kinderdijk\'teki değirmenler bu suyu daha yüksekteki kanallara ve akarsuya pompalamak için kurulmuştur.'),
  ('Rotterdam\'ın Avrupa\'nın en işlek limanlarından biri olmasında en etkili coğrafi etken hangisidir?', 'Ren-Meuse deltasında iç kesimlere açılması', ['Akdeniz\'e açılan doğal ve dar bir boğazın kıyısında bulunması', 'Kışın buz tutan kapalı bir körfezin tek çıkışında olması', 'Yüksek kayalıklarla korunan derin bir fiyordun içinde olması'], 'Rotterdam, Ren ve Meuse\'un denize ulaştığı deltada kuruludur. Ren su yolu Almanya\'nın Ruhr bölgesine ve İsviçre\'ye kadar uzanan geniş bir hinterlant sağlar.'),
  ('Belçika\'nın Kuzey Denizi\'ne açılan kıyısı için aşağıdakilerden hangisi doğrudur?', 'Kısa, düz ve kumullarla kaplı bir kıyıdır', ['Fiyortlarla parçalanmış uzun ve girintili bir kıyıdır', 'Yüksek tebeşir falezlerinden oluşur', 'Volkanik kayalıklarla çevrili bir kıyıdır'], 'Belçika\'nın kıyısı yaklaşık 65-70 km uzunluğundadır; düz kumsallar ve kumullarla kaplıdır. Oostende ve Zeebrugge başlıca limanlarıdır.'),
  ('Almanya\'da kuzeyden güneye doğru gidildiğinde yer şekillerinin genel sıralaması hangisidir?', 'Alçak ova, orta yükseklikte masifler, Alpler', ['Alpler, orta yükseklikte masifler, alçak ovalar', 'Orta yükseklikte masifler, Alpler, alçak ova', 'Alçak ova, Alpler, orta yükseklikteki masifler'], 'Kuzeyde Kuzey Alman Ovası, ortada Harz ve Kara Orman gibi orta yükseklikteki masifler, güneyde ise Bavyera Alpleri bulunur. Yani ülke kuzeyden güneye yükselir.'),
  ('Caspar David Friedrich\'in resmettiği beyaz tebeşir falezlerini görmek isteyen bir turist Stralsund\'dan köprüyle Almanya\'nın en büyük adasına geçiyor. Turist hangi adadadır?', 'Rügen', ['Sylt', 'Usedom', 'Fehmarn'], 'Rügen, Mecklenburg-Vorpommern kıyısındadır. Jasmund\'daki tebeşir falezleri ressam Caspar David Friedrich\'in tablolarıyla ün kazanmıştır.'),
  ('Büyük Britanya, Birleşik Krallık ve Britanya Adaları terimleriyle ilgili hangisi doğrudur?', 'Büyük Britanya bir ada, Birleşik Krallık bir devlettir', ['Üç terim de yalnızca İngiltere\'yi ifade eden eş anlamlılardır', 'Birleşik Krallık bir adanın, Büyük Britanya bir devletin adıdır', 'Britanya Adaları terimi yalnızca İrlanda adasını kapsar'], 'Büyük Britanya İngiltere, İskoçya ve Galler\'in bulunduğu adadır. Birleşik Krallık buna Kuzey İrlanda\'yı da katan devlettir. Britanya Adaları ise İrlanda adasını da içeren takımadanın coğrafi adıdır.'),
  ('İskoçya nüfusunun büyük bölümünün Glasgow ile Edinburgh arasındaki kesimde toplanmasının coğrafi nedeni hangisidir?', 'Bu kesimin alçak, düz ve ulaşıma elverişli olması', ['Bu kesimin İskoçya\'nın en yüksek dağlık alanı olması', 'Bu kesimde iklimin Akdeniz iklimine benzemesi', 'Bu kesimin denizden en uzak iç bölge olması'], 'Orta Alçak Bölge (Central Lowlands), kuzeydeki dağlık Highlands ile güneydeki Southern Uplands arasında kalır. Düzlüğü, kömür yatakları ve kıyıya açıklığı nüfusu burada toplamıştır.'),
  ('İrlanda\'nın Clare kontluğunda, Atlas Okyanusu\'na dik inen ve 200 metreye yaklaşan yükseklikleriyle tanınan kıyı kayalıkları hangisidir?', 'Moher Falezleri', ['Dover Falezleri', 'Slieve League Falezleri', 'Étretat Falezleri'], 'Moher Falezleri, Atlas dalgalarının kumtaşı ve şeyl katmanlarını aşındırmasıyla oluşmuş dik kıyı yarlarıdır ve İrlanda\'nın en çok ziyaret edilen doğal alanlarındandır.'),
  ('İrlanda\'da yüzyıllar boyunca kırsal evlerde yakıt olarak kesilip kurutulan, bataklıklarda biriken yarı çürümüş bitki maddesi hangisidir?', 'Turba', ['Linyit', 'Antrasit', 'Petrol şisti'], 'Serin ve yağışlı İrlanda\'da bitkiler bataklıklarda tam çürümeden birikerek turbayı oluşturur. Ağacı az olan adada turba uzun süre başlıca ev yakıtı olmuştur.'),
  ('İber Yarımadası anakarasının en yüksek zirvesi Mulhacén\'e tırmanmak isteyen bir dağcı Granada\'dan yola çıkıyor. Dağcının tırmanacağı dağ sırası hangisidir?', 'Sierra Nevada', ['Kantabria Dağları', 'Sierra Morena', 'Sistema Central'], 'Yaklaşık 3.479 m\'lik Mulhacén, Endülüs\'te Granada\'nın güneydoğusundaki Sierra Nevada\'dadır; Pireneler\'deki Aneto\'dan da yüksektir.'),
  ('İspanya\'nın kuzey kıyısına paralel uzanan ve Picos de Europa kütlesini de içeren dağ sırası hangisidir?', 'Kantabria Dağları', ['Sierra Nevada', 'Sierra Morena', 'Betik Kordilyera'], 'Kantabria Dağları Pireneler\'in batıya devamı gibi Biskay kıyısı boyunca uzanır. Picos de Europa bu sıranın en yüksek kireçtaşı kütlesidir.'),
  ('İspanya\'nın kuzeyindeki Galiçya, Asturias ve Bask bölgeleri için \'Yeşil İspanya\' deyiminin kullanılmasının nedeni nedir?', 'Okyanusal iklimin etkisiyle yıl boyu yağış alması', ['Ülkenin en geniş zeytinliklerine ve bağlarına sahip olması', 'Akdeniz\'e en uzun kıyısı olan bölgeler olması', 'Yazları çok sıcak ve kurak geçen yüksek bir plato olması'], 'Kuzey kıyısı Atlas Okyanusu\'ndan gelen nemli batı rüzgârlarına açıktır ve Kantabria Dağları yağışı artırır. Bu yüzden orman ve çayırlar yeşildir, oysa iç Meseta yazın kurur.'),
  ('Portekiz\'in güneyinde, kayalık falezleri ve kumsallarıyla tanınan turistik kıyı bölgesi hangisidir?', 'Algarve', ['Alentejo', 'Minho', 'Ribatejo'], 'Algarve, Portekiz\'in güney kıyısıdır; ılık iklimi ve falezleriyle Avrupa\'nın önemli tatil bölgelerindendir. Faro bu bölgenin merkezidir.'),
  ('İtalya\'da \'Mezzogiorno\' terimi hangi bölgeyi anlatır?', 'Kuzeyin gerisinde kalan güney İtalya ve adaları', ['Alpler\'deki yüksek dağ köylerini ve kayak merkezlerini', 'Po Ovası\'ndaki büyük sanayi kentlerini', 'Roma\'yı çevreleyen başkent bölgesini ve kıyılarını'], 'Mezzogiorno (\'öğle vakti\') Napoli\'nin güneyindeki bölgeler ile Sicilya ve Sardinya\'yı kapsar. İtalya\'nın kuzey-güney gelişmişlik farkı bu terimle anılır.'),
  ('Ligurya kıyısındaki dik yamaçlara kurulmuş, teraslı bağları ve renkli evleriyle tanınan beş köyden oluşan UNESCO alanı hangisidir?', 'Cinque Terre', ['Amalfi Kıyısı', 'Cilento', 'Portofino'], 'Cinque Terre (Beş Topraklar), denize dik inen yamaçlara kurulmuş beş köyden oluşur. Yüzyıllar boyunca taş duvarlarla yapılan teraslar tarıma olanak vermiştir.'),
  ('Sicilya ile Tunus arasında uzanan ve Akdeniz\'i doğu ile batı havzalarına ayıran su yolu hangisidir?', 'Sicilya Kanalı', ['Messina Boğazı', 'Otranto Boğazı', 'Bonifacio Boğazı'], 'Sicilya Kanalı (Sicilya Boğazı), Sicilya ile Tunus\'taki Bon Burnu arasında yaklaşık 145 km genişliğindedir ve Akdeniz\'in iki ana havzasını birbirinden ayırır.'),
  ('Yunanistan\'ın en geniş ovası olan ve ortasında Larisa kentinin bulunduğu ova hangisidir?', 'Teselya Ovası', ['Makedonya Ovası', 'Attika Ovası', 'Argolis Ovası'], 'Teselya Ovası, Pindus ile Olimpos-Ossa dağları arasında kalan verimli bir çanaktır ve Yunanistan\'ın tahıl ambarı sayılır.'),
  ('Teselya\'da, dev kumtaşı ve konglomera sütunlarının tepesine kurulmuş manastırlarıyla tanınan yer hangisidir?', 'Meteora', ['Aynaroz', 'Delfi', 'Mistra'], 'Meteora\'daki kaya sütunları milyonlarca yıllık aşınmayla oluşmuştur. Keşişler 14. yüzyıldan itibaren bu sütunların tepesine manastırlar kurmuştur.'),
  ('Girit\'ten sonra Yunanistan\'ın en büyük adası olan ve anakaraya köprülerle bağlanan ada hangisidir?', 'Eğriboz', ['Rodos', 'Midilli', 'Korfu'], 'Eğriboz, Attika ve Beotya kıyısı boyunca uzanan uzun bir adadır. Halkis\'te anakara ile arasındaki dar Euripos Boğazı\'nın üzerinden köprüyle bağlanır.'),
  ('Yunanistan\'ın ikinci büyük kenti Selanik hangi körfezin kıyısındadır?', 'Termaik Körfezi', ['Saronik Körfezi', 'Korint Körfezi', 'Argolis Körfezi'], 'Selanik, Ege\'nin kuzeybatısındaki Termaik (Selanik) Körfezi\'nin kuzey ucunda kurulmuştur. Saronik Körfezi ise Atina ve Pire\'nin önündedir.'),
  ('Yunanistan\'da tarım alanlarının az, kıyı yerleşmelerinin ve denizciliğin ise eski çağlardan beri önemli olmasının temel coğrafi nedeni nedir?', 'Ülkenin dağlık, kıyılarının girintili ve adalı olması', ['Ülkenin geniş ve verimli iç ovalarla kaplı olması', 'Kıyılarının sığ, bataklık ve sıtmalı olması', 'Ülkenin denizden uzak, yüksek bir iç plato olması'], 'Yunanistan\'ın büyük bölümü dağlıktır; ovalar küçük ve dağınıktır. Buna karşın uzun ve girintili kıyılar ile binlerce ada denizciliği ve kıyı yerleşmesini özendirmiştir.'),
  ('Kireçtaşı arazilerdeki çözünme şekillerinin genel adı olan \'karst\' sözcüğü hangi bölgenin adından gelir?', 'Slovenya\'daki Kras platosundan', ['Hırvatistan\'daki Dalmaçya kıyısının eski adından', 'Avusturya\'daki Karawanken dağlarından', 'Bosna\'daki Neretva vadisinin yerel adından'], 'Trieste\'nin gerisindeki Kras (Karst) platosu, kireçtaşı çözünme şekillerinin ilk kez bilimsel olarak incelendiği yerdir. Bölgenin adı bu şekillerin genel adı olmuştur.'),
  ('Mostar\'da Osmanlı döneminden kalma taş köprüden suya atlayan dalgıçları izleyen bir turist, köprünün altından akan akarsuyu görüyor. Bu akarsu hangisidir?', 'Neretva', ['Drina', 'Sava', 'Bosna'], 'Neretva, Bosna-Hersek\'in güneyinden geçip Hırvatistan\'da Adriyatik\'e dökülür. Mostar\'daki Osmanlı köprüsü bu akarsuyun üzerindedir.'),
  ('Slovenya\'nın en yüksek dağı olan ve ülkenin bayrağında stilize biçimde yer alan zirve hangisidir?', 'Triglav', ['Grossglockner', 'Lovćen', 'Durmitor'], 'Yaklaşık 2.864 m\'lik Triglav Julian Alpleri\'ndedir. Üç başlı silueti Slovenya bayrağı ve armasında simgelenir.'),
  ('Bosna-Hersek ile Sırbistan arasındaki sınırın büyük bölümünü oluşturan ve Višegrad\'daki Osmanlı köprüsüyle tanınan akarsu hangisidir?', 'Drina', ['Neretva', 'Morava', 'Una'], 'Drina, Sava\'nın bir koludur ve iki ülke arasında doğal sınır çizer. Višegrad\'daki Sokullu Mehmed Paşa Köprüsü bu akarsuyun üzerindedir.'),
  ('İsviçre nüfusunun ve büyük kentlerinin çoğunun Alpler ile Jura arasındaki kesimde toplanmasının nedeni nedir?', 'Alçak tepeli ve tarıma, ulaşıma elverişli olması', ['Bu kesimin İsviçre\'nin en yüksek dağlık alanı olması', 'Bu kesimin yıl boyu tümüyle buzullarla kaplı olması', 'Bu kesimin denize kıyısı olan tek bölge olması'], 'Mittelland (İsviçre Platosu) Cenevre Gölü\'nden Konstanz Gölü\'ne uzanır. Zürih, Bern ve Lozan gibi kentler bu daha alçak ve verimli kesimdedir.'),
  ('Ren, Ron, Tuna\'nın kolu Inn ve Po\'nun kolu Ticino gibi akarsuların kaynaklarını barındırdığı için Avrupa\'nın \'su kulesi\' diye anılan ülke hangisidir?', 'İsviçre', ['Avusturya', 'Almanya', 'Fransa'], 'İsviçre Alpleri\'nden doğan akarsular Kuzey Denizi\'ne, Akdeniz\'e, Adriyatik\'e ve Karadeniz\'e ulaşır. Bu yüzden ülke kıtanın su deposu sayılır.'),
  ('Bern\'in eski kentini dolaşan bir turist, kentin üç yanını çeviren derin bir menderesin içinde olduğunu fark ediyor. Bu menderesi çizen akarsu hangisidir?', 'Aare', ['Ren', 'Reuss', 'Limmat'], 'Bern\'in eski kenti, Aare\'nin çizdiği derin bir menderesin içindeki yarımadaya kurulmuştur. Bu konum ortaçağda doğal bir savunma sağlamıştır.'),
  ('Innsbruck\'ta kentin içinden geçen akarsu üzerindeki köprüde duran bir turist, kente adını veren akarsuyu izlemektedir. Bu akarsu hangisidir?', 'Inn', ['Salzach', 'Enns', 'Mur'], 'Innsbruck adını \'Inn üzerindeki köprü\' anlamından alır. Inn vadisi Alpler içinde batı-doğu doğrultusunda önemli bir ulaşım koridorudur.'),
  ('Avusturya\'daki Hallstatt kasabası ve çevresi, tarih öncesinden beri hangi doğal kaynağın çıkarılmasıyla tanınır?', 'Kaya tuzu', ['Altın', 'Bakır', 'Kehribar'], 'Hallstatt\'taki tuz madenleri yaklaşık 7.000 yıldır işletilir. Erken Demir Çağı\'ndaki \'Hallstatt kültürü\' adını bu yerleşmeden alır.'),
  ('Polonya ile Beyaz Rusya sınırında uzanan, Avrupa\'nın son büyük ova ormanlarından biri olan ve Avrupa bizonunun korunduğu orman hangisidir?', 'Białowieża Ormanı', ['Kara Orman', 'Bohemya Ormanı', 'Tatra Ormanı'], 'Białowieża, Avrupa ovalarını bir zamanlar kaplayan karışık ormanların bozulmadan kalan bir parçasıdır. Neredeyse tükenen Avrupa bizonu burada yeniden çoğaltılmıştır.'),
  ('Çekya\'nın batısında, sıcak mineralli su kaynaklarıyla 18. yüzyıldan beri ünlü kaplıca kenti hangisidir?', 'Karlovy Vary', ['Brno', 'Ostrava', 'Olomouc'], 'Karlovy Vary (Karlsbad), Bohemya\'nın batısındaki sıcak kaynaklar üzerinde kurulmuştur. Avrupa\'nın önde gelen kaplıca kentlerindendir.'),
  ('Romanya\'da Tuna\'nın aşağı çığırı ile Karadeniz arasında kalan, Köstence limanının da bulunduğu tarihî bölge hangisidir?', 'Dobruca', ['Eflak', 'Banat', 'Bukovina'], 'Dobruca, Tuna\'nın kuzeye kıvrılarak deltasına ulaştığı yer ile Karadeniz arasında kalan alçak bir platodur. Kuzeyi Romanya\'da, güneyi Bulgaristan\'dadır.'),
  ('Bulgaristan\'da Balkan Dağları ile Sredna Gora arasında uzanan ve gül yağı üretimiyle dünyaca tanınan vadi hangi kentle anılır?', 'Kazanlık', ['Varna', 'Pleven', 'Vidin'], 'Kazanlık Gül Vadisi, iki dağ sırasının koruduğu ılıman ve nemli bir çanaktır. Bu koşullar yağ gülü yetiştirmeye çok uygundur.'),
  ('Bulgaristan\'ın ikinci büyük kenti Filibe (Plovdiv) hangi akarsuyun kıyısında ve hangi ovadadır?', 'Meriç kıyısında, Yukarı Trakya Ovası\'nda', ['Tuna kıyısında, Eflak Ovası\'nda', 'İskar kıyısında, Sofya Ovası\'nda', 'Struma kıyısında, Makedonya Ovası\'nda'], 'Filibe, Rodoplar ile Sredna Gora arasındaki Yukarı Trakya Ovası\'nda, Meriç (Maritsa) Nehri\'nin iki yakasına kurulmuştur.'),
  ('Ukrayna\'nın en yüksek zirvesi Hoverla hangi dağ sırasındadır?', 'Doğu Karpatlar', ['Kırım Dağları', 'Ural Dağları', 'Kafkas Dağları'], 'Yaklaşık 2.061 m\'lik Hoverla, Ukrayna\'nın batısındaki Karpatlar\'ın Çornohora kesimindedir.'),
  ('Kırım Yarımadası\'nın güney kıyısında Yalta çevresinde Akdeniz iklimine benzer ılık kışların görülmesinin başlıca nedeni nedir?', 'Soğuk kuzey havasının dağlarca engellenmesi', ['Kıyıya Golf Akıntısı\'nın sıcak sularının ulaşması', 'Bölgenin ekvatora Akdeniz kıyılarından daha yakın olması', 'Kıyının alçak ve kuzeye açık geniş bir ova olması'], 'Kırım Dağları güney kıyıya paralel uzanarak step üzerinden gelen soğuk kuzey rüzgârlarını keser. Dağlarla deniz arasındaki dar kıyı şeridi bu yüzden ılıman kalır.'),
  ('Ukrayna\'nın doğusunda 19. yüzyıldan beri zengin taş kömürü yataklarına dayalı bir sanayi bölgesi olan havza hangisidir?', 'Donets Havzası', ['Polesya Havzası', 'Dinyeper Havzası', 'Galiçya Havzası'], 'Donets Havzası (Donbas) taş kömürü yataklarıyla Doğu Avrupa\'nın önemli ağır sanayi alanlarından biri olmuştur.'),
  ('Beyaz Rusya\'nın güneyi ile Ukrayna\'nın kuzeyini kaplayan, Avrupa\'nın en geniş bataklık alanlarından biri olan bölge hangisidir?', 'Polesya', ['Mazurya Göller Bölgesi', 'Volga Deltası', 'Valday Tepeleri'], 'Polesya, Pripyat Nehri ve kollarının geçtiği düz ve kötü drene olan bir ovadır. Geniş bataklıkları tarihte orduların geçişini bile zorlaştırmıştır.'),
  ('Litvanya\'ya deniz yoluyla konteyner göndermek isteyen bir şirket, ülkenin Kür Lagünü\'nün denize açıldığı yerdeki tek büyük limanını kullanacaktır. Bu liman hangisidir?', 'Klaipėda', ['Riga', 'Liepāja', 'Kaunas'], 'Litvanya\'nın kısa kıyısındaki Klaipėda, Kür Lagünü\'nün denize açıldığı boğazda kurulmuştur. Riga ve Liepāja Letonya\'da, Kaunas ise iç kesimdedir.'),
  ('Estonya, Letonya ve Litvanya\'nın yer şekilleri için ortak olarak aşağıdakilerden hangisi söylenebilir?', 'Buzulların biçimlendirdiği alçak, göllü düzlüklerdir', ['Genç kıvrım dağlarıyla kaplı yüksek ülkelerdir', 'Volkanik platolar ve kraterlerle örtülü alanlardır', 'Kireçtaşı karstıyla kaplı kurak arazilerdir'], 'Baltık ülkelerinde en yüksek noktalar 350 metreyi geçmez. Son buzullaşmanın bıraktığı morenler, göller ve bataklıklar bu ülkelerin yüzeyini biçimlendirmiştir.'),
  ('Norveç\'in en uzun ve en derin fiyordu olan, Bergen\'in kuzeyinde iç kesimlere 200 km\'yi aşkın uzanan fiyort hangisidir?', 'Sognefjord', ['Oslofjord', 'Trondheimsfjord', 'Lysefjord'], 'Sognefjord yaklaşık 200 km uzunluğu ve 1.300 metreyi aşan derinliğiyle Norveç\'in en büyük fiyordudur.'),
  ('Norveç\'te elektriğin çok büyük bölümünün hidroelektrik santrallerinden üretilebilmesini sağlayan koşul hangisidir?', 'Bol yağış ve dik yükselti farkı', ['Geniş ve düz akarsu deltaları', 'Yıl boyu kurak geçen iklim', 'Büyük linyit yataklarının bulunması'], 'Batı rüzgârlarının getirdiği bol yağış, dağlardaki kar ve buzullar ile kıyıya doğru hızla alçalan arazi akarsulara büyük enerji potansiyeli kazandırır.'),
  ('İsveç\'in başkenti Stockholm\'ün adalar üzerine kurulmasının nedeni hangi coğrafi konumda yer almasıdır?', 'Mälaren Gölü\'nün Baltık\'a açıldığı yerde', ['Göta Nehri\'nin Kattegat\'a döküldüğü yerde', 'Vättern Gölü\'nün güney ucunda', 'Bothnia Körfezi\'nin kuzey ucunda'], 'Stockholm, Mälaren Gölü\'nün suyunu Baltık Denizi\'ne boşalttığı geçitteki adalar ve yarımadalar üzerinde kurulmuştur.'),
  ('Öresund Köprüsü\'nü geçerek Kopenhag\'dan İsveç\'e giren bir sürücü, ilk olarak verimli tarım alanlarıyla tanınan hangi İsveç bölgesine ulaşır?', 'Skåne', ['Norrland', 'Dalarna', 'Värmland'], 'Skåne, Danimarka\'ya Öresund ile komşu olan alçak ve verimli bir ovadır. İsveç\'in geri kalanına göre ılıman iklimi tarımı kolaylaştırır.'),
  ('İsveç\'in doğu ve batı kıyılarını iç göller üzerinden birbirine bağlayan, 19. yüzyılda açılmış ünlü su yolu hangisidir?', 'Göta Kanalı', ['Kiel Kanalı', 'Saimaa Kanalı', 'Kaledonya Kanalı'], 'Göta Kanalı, Vänern ve Vättern göllerini kullanarak Göteborg tarafını Baltık kıyısına bağlar. Bugün daha çok turistik bir su yoludur.'),
  ('Finlandiya Laponyası\'nın merkezi olan ve kuzey kutup dairesinin hemen üzerinde yer alan kent hangisidir?', 'Rovaniemi', ['Oulu', 'Tampere', 'Turku'], 'Rovaniemi, Kemi ve Ounas akarsularının birleştiği yerde kurulmuştur. Kentin hemen kuzeyinden kutup dairesi geçer.'),
  ('Hans Christian Andersen\'in doğduğu evi görmek isteyen bir turist Kopenhag\'dan batıya trenle Büyük Kuşak\'ı geçerek Odense\'ye gidiyor. Turist hangi adaya varmıştır?', 'Funen', ['Zelanda', 'Bornholm', 'Lolland'], 'Odense, Zelanda ile Jutland arasındaki Funen Adası\'nın merkezidir.'),
  ('St. Petersburg\'da haziran ayında gecelerin tam kararmadığı, alacakaranlıkla geçtiği \'Beyaz Geceler\'in yaşanmasının nedeni nedir?', 'Kutup dairesine yakın yüksek bir enlemde olması', ['Kentin kuzey kutup dairesinin kuzeyinde bulunması', 'Kentin Neva deltasında alçak ve sisli bir yerde olması', 'Kentin üzerinde yazın sürekli kutup ışıkları oluşması'], 'St. Petersburg yaklaşık 60° kuzey enlemindedir. Güneş yazın ufkun altına yalnızca biraz indiğinden gece boyu alacakaranlık sürer; ancak kent kutup dairesinin güneyinde kaldığı için güneş yine de batar.'),
  ('Kuzey ışıklarını (aurora borealis) izlemek için kış aylarında Norveç\'in kuzeyi, Finlandiya Laponyası ve İzlanda\'nın tercih edilmesinin coğrafi nedeni hangisidir?', 'Manyetik kutbu çevreleyen aurora kuşağına yakınlık', ['Bu yerlerde kış boyunca güneşin hiç batmaması', 'Bu yerlerin ekvatora görece yakın konumda olması', 'Bu yerlerde kışın havanın sürekli bulutlu olması'], 'Güneş rüzgârı parçacıkları Dünya\'nın manyetik alanınca kutuplara yönlendirilir ve manyetik kutbu halka gibi çevreleyen bir kuşakta auroralar oluşturur. Kış gecelerinin uzun ve karanlık olması da gözlemi kolaylaştırır.'),
  ('Cenevre kentinin kurulduğu yer için en doğru tanım hangisidir?', 'Ron Nehri\'nin Cenevre Gölü\'nden çıktığı noktadır', ['Ren Nehri\'nin Konstanz Gölü\'ne girdiği yerdir', 'Aare Nehri\'nin Ren\'e katıldığı alçak ovadır', 'Ron Nehri\'nin Akdeniz\'e döküldüğü deltadır'], 'Ron, Valais\'den gelerek Cenevre Gölü\'ne girer ve gölün güneybatı ucunda, Cenevre kentinde gölden çıkarak Fransa\'ya akar.'),
  ('Bugün Polonya ve Çekya arasında paylaşılan, Oder\'in yukarı çığırında yer alan ve kömür yataklarıyla tanınan tarihî bölge hangisidir?', 'Silezya', ['Pomeranya', 'Bohemya', 'Galiçya'], 'Silezya, Oder havzasının yukarı kesimidir. Yukarı Silezya kömür havzası Katowice çevresinde önemli bir sanayi bölgesi oluşturmuştur.'),
  ('Bugün Finlandiya ile Rusya arasında bölünmüş olan, göller ve ormanlarla kaplı tarihî bölge hangisidir?', 'Karelya', ['Laponya', 'İngria', 'Pomeranya'], 'Karelya, Ladoga ve Onega gölleri çevresinden Beyaz Deniz\'e uzanır. Batı kesimi 1940\'tan sonra Sovyetler Birliği\'ne geçmiş, küçük bir bölümü Finlandiya\'da kalmıştır.'),
  ('Avrasya anakarasının en doğu ucu olan ve Bering Boğazı\'na bakan burun hangisidir?', 'Dejnev Burnu', ['Çelyuskin Burnu', 'Lopatka Burnu', 'Nordkinn Burnu'], 'Çukotka Yarımadası\'ndaki Dejnev Burnu, Alaska\'ya yaklaşık 80 km uzaklıktadır ve Asya anakarasının en doğu noktasıdır.'),
  ('Taymır Yarımadası\'nın ucunda yer alan ve Avrasya anakarasının en kuzey noktası olan burun hangisidir?', 'Çelyuskin Burnu', ['Dejnev Burnu', 'Nordkapp', 'Roca Burnu'], 'Yaklaşık 77°43\' kuzey enlemindeki Çelyuskin Burnu, Asya ve Avrasya anakarasının en kuzey noktasıdır.'),
  ('Rusya\'nın kara sınırı bulunan Kuzey Avrupa ülkeleri hangi seçenekte doğru verilmiştir?', 'Norveç ve Finlandiya', ['İsveç ve Finlandiya', 'Norveç ve İsveç', 'Danimarka ve Norveç'], 'Rusya, Kola Yarımadası\'nın kuzeyinde Norveç ile, Karelya boyunca Finlandiya ile sınır komşusudur. İsveç ve Danimarka\'nın Rusya ile kara sınırı yoktur.'),
  ('Bering Boğazı\'nın ortasındaki iki Diomede adasından büyüğü Rusya\'ya, küçüğü ABD\'ye aittir. Bu iki adanın aralarında yalnızca birkaç kilometre olmasına karşın takvimde bir gün farkla yaşamasının nedeni nedir?', 'Tarih değiştirme çizgisinin aralarından geçmesi', ['Adaların ekvatorun farklı yanlarında, farklı yarım kürelerde olması', 'Adalar arasında on iki saatlik bir enlem farkı bulunması', 'Rusya\'nın bu adada yaz saati uygulamasını kaldırmış olması'], 'Tarih değiştirme çizgisi Bering Boğazı\'nda iki adanın arasından geçer. Bu yüzden Büyük Diomede, Küçük Diomede\'den takvim bakımından neredeyse bir gün ileridedir.'),
  ('Kuzey kutup dairesinin kuzeyinde kurulmuş en kalabalık kent olarak bilinen Rus kenti hangisidir?', 'Murmansk', ['Arhangelsk', 'Norilsk', 'Vorkuta'], 'Murmansk, Kola Yarımadası\'nda kutup dairesinin yaklaşık 2 derece kuzeyindedir ve bu enlemdeki en büyük kenttir. Arhangelsk ise kutup dairesinin güneyindedir.'),
  ('Yenisey ile Lena nehirleri arasında uzanan, akarsuların derin vadiler açtığı yüksek ve geniş yer şekli hangisidir?', 'Orta Sibirya Platosu', ['Batı Sibirya Ovası', 'Verhoyansk Dağları', 'Valday Tepeleri'], 'Orta Sibirya Platosu ortalama 500-700 m yükseltide, eski bir kalkan üzerinde yer alan ve bazalt örtüleri barındıran geniş bir platodur.'),
  ('Lena Nehri\'nin doğusunda yay çizerek uzanan ve dünyanın en soğuk yerleşmelerinden biri olan Verhoyansk\'a adını veren dağ sırası hangisidir?', 'Verhoyansk Dağları', ['Sayan Dağları', 'Ural Dağları', 'Altay Dağları'], 'Verhoyansk Dağları Doğu Sibirya\'dadır. Dağların çevrelediği çanaklarda kışın soğuk hava birikerek aşırı düşük sıcaklıklara yol açar.'),
  ('Kafkasların en yüksek zirvesi Elbruz\'un yapısı için aşağıdakilerden hangisi doğrudur?', 'İki zirveli, sönmüş sayılan bir volkandır', ['Kireçtaşından oluşmuş bir karst kütlesidir', 'Granitten oluşmuş yaşlı bir masiftir', 'Buzul birikintilerinden oluşmuş bir tepedir'], 'Yaklaşık 5.642 m yükseltideki Elbruz, batı ve doğu olmak üzere iki zirvesi olan bir stratovolkandır; tepesi kalıcı buzullarla örtülüdür.'),
  ('Ural Dağları\'nın görece alçak ve yuvarlak hatlı olmasının nedeni nedir?', 'Çok eski olup uzun süre aşınmış olması', ['Genç bir volkanik kuşak olup henüz yükselmemiş olması', 'Buzulların dağları tamamen örtüp düzleştirmiş olması', 'Bir graben sisteminin çökmüş bir parçası olması'], 'Ural Dağları Paleozoyik\'in sonunda oluşmuştur. Yüz milyonlarca yıllık aşınma dağları alçaltmış; en yüksek noktası Narodnaya yaklaşık 1.895 m\'de kalmıştır.'),
  ('Ural Dağları\'nın ekonomik önemini artıran başlıca doğal özellik hangisidir?', 'Demir, bakır ve değerli taş yatakları', ['Dünyanın en büyük buzul alanlarını barındırması', 'Yıl boyu ılık iklimi ve çok verimli toprakları', 'Etkin volkanlarının bol jeotermal enerji sağlaması'], 'Yaşlı ve aşınmış Ural kuşağında demir, bakır, nikel, altın ve değerli taşlar yüzeye yakındır. Bu yüzden Yekaterinburg gibi kentler 18. yüzyıldan beri madencilik merkezi olmuştur.'),
  ('Hazar Denizi\'nin kuzeyinde, Volga ve Ural nehirlerinin aşağı çığırını kapsayan alçak alanın en belirgin özelliği nedir?', 'Büyük bölümünün okyanus düzeyinin altında olması', ['Yüksek bir dağ platosunun kuzey uzantısı olması', 'Tümüyle sık tayga ormanlarıyla kaplı olması', 'Fiyortlarla parçalanmış girintili bir kıyıya sahip olması'], 'Hazar Çöküntüsü, Hazar Denizi\'nin yüzeyi gibi okyanus düzeyinin yaklaşık 28 m altındadır. Yarı kurak bir step ve yarı çöl alanıdır.'),
  ('Çin\'deki Altay Dağları\'ndan doğup Kazakistan\'ı geçtikten sonra Rusya\'da Ob\'a katılan ve onun en uzun kolu olan akarsu hangisidir?', 'İrtiş', ['Angara', 'Tobol', 'Katun'], 'İrtiş, Ob\'un en büyük koludur; Omsk\'tan geçerek Hantı-Mansiysk yakınlarında Ob\'a katılır. Ob-İrtiş birlikte Asya\'nın en uzun akarsu sistemlerinden birini oluşturur.'),
  ('Ob Nehri, Arktik Okyanusu\'nun hangi kenar denizine açılan uzun bir körfezle dökülür?', 'Kara Denizi', ['Barents Denizi', 'Laptev Denizi', 'Beyaz Deniz'], 'Ob, yaklaşık 800 km uzunluğundaki Ob Körfezi\'nden Kara Denizi\'ne ulaşır. Yenisey de aynı denize dökülür.'),
  ('Baykal Gölü\'nden çıkan tek akarsu olan ve Irkutsk\'tan geçerek Yenisey\'e katılan nehir hangisidir?', 'Angara', ['Selenga', 'Lena', 'Barguzin'], 'Baykal\'a 300\'ü aşkın akarsu dökülür, ancak gölden çıkan tek akarsu Angara\'dır. Angara üzerinde büyük hidroelektrik barajları kurulmuştur.'),
  ('Mersin balığı avcılığını yerinde görmek isteyen bir gezgin, Volga\'nın Hazar\'a dökülmeden önce kollara ayrıldığı deltanın başındaki kente gidiyor. Bu kent hangisidir?', 'Astrahan', ['Volgograd', 'Samara', 'Saratov'], 'Astrahan, Volga deltasının yukarı ucundadır. Delta, Avrupa\'nın en büyük nehir deltasıdır ve mersin balığı avcılığıyla tanınır.'),
  ('Baykal Gölü\'ne özgü olan ve dünyada yalnız tatlı suda yaşayan birkaç fok türünden biri olan canlı hangisidir?', 'Nerpa', ['Mors', 'Deniz aslanı', 'Kürklü fok'], 'Baykal foku (nerpa) yalnız Baykal Gölü\'nde yaşar. Denizden binlerce kilometre uzaktaki bu göle nasıl ulaştığı hâlâ tartışılmaktadır.'),
  ('Doğu Sibirya\'daki Verhoyansk\'ta kışın −60 °C\'nin altına inen sıcaklıklar yazın 30 °C\'yi aşabilir. Bu durum en iyi hangi kavramla açıklanır?', 'Aşırı karasallık', ['Okyanusal ılımanlık', 'Yükselti etkisi', 'Muson etkisi'], 'Verhoyansk okyanuslardan çok uzak, dağlarla çevrili bir çanaktadır. Kara kışın çok soğur, yazın ise uzun gündüzlerle hızla ısınır; bu yüzden yıllık sıcaklık farkı dünyadaki en büyük değerlere ulaşır.'),
  ('Yakutsk\'ta çok katlı binaların toprağa gömülü kazıklar üzerine, zeminle arasında boşluk bırakılarak yapılmasının amacı nedir?', 'Binanın ısısının donmuş zemini çözüp çökertmesini önlemek', ['Bahar taşkınlarında binaların su altında kalmasını önlemek', 'Deprem dalgalarının binaya ulaşmasını engellemek', 'Kar yağışının binanın altında birikmesini sağlamak'], 'Yakutsk kalın bir permafrost katmanı üzerindedir. Bina doğrudan zemine otursa ısısı buzu eritir ve zemin çöker. Altta bırakılan boşlukta soğuk hava dolaşarak zeminin donuk kalmasını sağlar.'),
  ('Rusya topraklarının ne kadarlık bölümü sürekli ya da kesintili permafrost ile kaplıdır?', 'Yarıdan fazlası', ['Onda biri kadarı', 'Dörtte biri kadarı', 'Neredeyse hiç'], 'Rusya\'nın yaklaşık üçte ikisinde, özellikle Sibirya ve Uzak Doğu\'da, yıl boyu donuk kalan toprak katmanı bulunur.'),
  ('Rusya\'nın tahıl üretiminin önemli bir bölümünün güneydeki Kuban, Stavropol ve Volga\'nın aşağı kesimlerinde yapılmasının nedeni nedir?', 'Çernozyom topraklı step kuşağında olmaları', ['Bu kesimlerin sık tayga ormanlarıyla kaplı olması', 'Bu kesimlerin kalın bir permafrost üzerinde bulunması', 'Bu kesimlerin ağaçsız tundra kuşağında yer alması'], 'Güney Rusya\'nın step kuşağındaki çernozyom (kara toprak) çok verimlidir. Görece uzun ve sıcak yazlar da tahıl tarımını kolaylaştırır.'),
  ('Rusya\'nın kuzeyinde, tundranın da kuzeyinde kalan Franz Josef Land ve Severnaya Zemlya gibi takımadalarda görülen doğal kuşak hangisidir?', 'Arktik çöl', ['Orman-tundra', 'Step', 'Tayga'], 'Arktik çöl kuşağında yaz çok kısa ve soğuktur; yüzeyin büyük bölümü buzul ve çıplak kayalıktır. Bitki örtüsü yalnızca yosun ve likenlerden oluşan seyrek lekelerdir.'),
  ('Ural Dağları\'nın doğu yamacında kurulan ve Avrupa ile Asya arasındaki geçişin kapısı sayılan Rus kenti hangisidir?', 'Yekaterinburg', ['Perm', 'Ufa', 'Samara'], 'Yekaterinburg, 1723\'te Ural madenlerini işletmek için kurulmuştur. Trans-Sibirya hattı da Ural\'ı bu kent üzerinden aşar.'),
  ('Yenisey Nehri\'nin kıyısında kurulan ve nehir üzerindeki köprüsüyle de tanınan Orta Sibirya\'nın büyük kenti hangisidir?', 'Krasnoyarsk', ['Novosibirsk', 'Tomsk', 'Habarovsk'], 'Krasnoyarsk, Yenisey\'in Batı Sayan dağlarından çıkıp ovaya ulaştığı yerdedir. Yakınındaki Krasnoyarsk barajı Rusya\'nın en büyük hidroelektrik santrallerindendir.'),
  ('Trans-Sibirya hattının kuzeyinden geçerek Baykal Gölü\'nün kuzey ucunu Pasifik kıyısına bağlayan ikinci büyük Sibirya demiryolu hangisidir?', 'Baykal-Amur Ana Hattı', ['Türkistan-Sibirya (Türksib) Demiryolu', 'Kuzey Kutup Dairesi Demiryolu', 'Çin Doğu (Mançurya) Demiryolu'], 'BAM, Taişet\'ten başlayıp Baykal\'ın kuzeyinden geçerek Tatar Boğazı kıyısındaki Sovetskaya Gavan\'a ulaşır. Hat, permafrost ve dağlık arazi nedeniyle yapımı en zor demiryollarından biri olmuştur.'),
  ('Volga ile Don nehirlerinin birbirine en çok yaklaştığı yerde açılan ve Hazar ile Azak denizlerini birbirine bağlayan kanal hangi kentin yakınındadır?', 'Volgograd', ['Rostov', 'Astrahan', 'Samara'], 'Volga-Don Kanalı 1952\'de Volgograd\'ın güneyinde açılmıştır. Böylece Hazar\'dan Azak ve Karadeniz\'e kesintisiz su yolu kurulmuştur.'),
  ('Denizden uzak olmasına karşın Moskova\'ya \'beş denizin limanı\' denmesinin nedeni nedir?', 'Su yollarıyla beş ayrı denize bağlanması', ['Kentin beş ayrı denizin kıyısında kurulmuş olması', 'Kentte beş büyük deniz müzesinin bulunması', 'Kentten beş denize demiryolu hatlarının uzanması'], 'Moskova Kanalı kenti Volga\'ya bağlar. Volga-Baltık su yolu, Beyaz Deniz-Baltık Kanalı ve Volga-Don Kanalı ile kentten beş denize gemiyle ulaşılabilir.'),
  ('Sahalin Adası\'nı Rusya anakarasından ayıran dar su yolu hangisidir?', 'Tatar Boğazı', ['La Pérouse Boğazı', 'Bering Boğazı', 'Kerç Boğazı'], 'Tatar Boğazı Sahalin ile anakara arasındadır. Adanın güneyindeki La Pérouse (Soya) Boğazı ise Sahalin\'i Japonya\'nın Hokkaido Adası\'ndan ayırır.'),
  ('Barents ile Kara denizlerini birbirinden ayıran ve Ural Dağları\'nın kuzeye uzantısı sayılan uzun takımada hangisidir?', 'Novaya Zemlya', ['Severnaya Zemlya', 'Franz Josef Land', 'Yeni Sibirya Adaları'], 'Novaya Zemlya iki büyük adadan oluşur ve Ural kıvrım kuşağının kuzey devamıdır. Soğuk Savaş döneminde Sovyet nükleer denemelerinin yapıldığı alanlardandır.'),
  ('Kara Denizi\'ne uzanan, büyük doğal gaz yataklarıyla ve Nenets ren geyiği çobanlarıyla tanınan, adı yerel dilde \'dünyanın sonu\' anlamına gelen yarımada hangisidir?', 'Yamal', ['Kola', 'Taymır', 'Çukotka'], 'Yamal Yarımadası Batı Sibirya\'nın kuzeyindedir. Permafrostlu tundrası altında Rusya\'nın en büyük doğal gaz rezervlerinden bazıları bulunur.'),
  ('Kamçatka\'da 1941\'de keşfedilen ve onlarca gayzeri bir arada barındıran, Avrasya\'nın en büyük gayzer alanı hangisidir?', 'Gayzerler Vadisi', ['Lena Sütunları', 'Altay\'ın Altın Dağları', 'Putorana Platosu'], 'Kamçatka\'daki Gayzerler Vadisi, Kronotski Doğa Koruma Alanı içindedir. Volkanik ısı, yer altı suyunu düzenli aralıklarla fışkırtır.'),
  ('Rusya\'nın Karadeniz kıyısındaki Soçi\'nin ülkenin geri kalanından farklı olarak ılık ve nemli bir iklime sahip olmasının nedeni nedir?', 'Kafkasların soğuk kuzey havasını engellemesi ve denizin ılıtması', ['Kentin Golf Akıntısı\'nın doğrudan etkisinde olması', 'Kentin ekvatora Moskova\'dan çok daha yakın olmasıyla tropikal kuşakta kalması', 'Kentin Hazar\'ın sıcak sularıyla çevrili olması'], 'Soçi, Büyük Kafkasların denize indiği dar bir kıyıdadır. Dağlar kuzeyden gelen soğuk havayı keserken Karadeniz kışları ılıklaştırır; bu yüzden Rusya\'nın nemli subtropikal kıyısıdır.'),
  ('Krasnodar\'da kentin güneyinden geçen ve Elbruz buzullarından gelip Azak Denizi\'ne doğru akan akarsuyun kıyısında yürüyen bir gezgin hangi akarsuyu görmektedir?', 'Kuban', ['Terek', 'Don Nehri', 'Kura'], 'Kuban Nehri Kuzey Kafkasya\'nın batısını sular. Havzası Rusya\'nın en verimli tarım bölgelerinden biridir.'),
  ('Hazar Denizi ile Kafkas Dağları arasındaki dar kıyı geçidini tutan ve tarih boyunca kuzey ile güney arasında stratejik bir kapı olan Dağıstan kenti hangisidir?', 'Derbent', ['Mahaçkale', 'Grozni', 'Nalçik'], 'Derbent, dağların Hazar\'a en çok yaklaştığı yerde kurulmuştur. Sasani dönemi surlarıyla UNESCO listesindedir ve \'Demir Kapı\' olarak anılmıştır.'),
  ('Kislovodsk, Pyatigorsk ve Yessentuki gibi kentlerin oluşturduğu, mineralli su kaynaklarıyla 19. yüzyıldan beri ünlü kaplıca bölgesi hangi dağ sırasının kuzey eteğindedir?', 'Kafkas Dağları', ['Ural Dağları', 'Altay Dağları', 'Karpat Dağları'], 'Kafkas Maden Suları bölgesi Stavropol\'ün güneyinde, Elbruz\'un kuzeyindeki volkanik kökenli tepeler arasında yer alır.'),
  ('Heidelberg\'in Eski Köprüsü\'nden geçen bir turist, Stuttgart\'tan gelip Mannheim\'da Ren\'e katılan akarsuyu izliyor. Bu akarsu hangisidir?', 'Neckar', ['Main', 'Mosel', 'Lahn'], 'Neckar, Kara Orman\'ın doğusundan doğar; Stuttgart ve Heidelberg\'den geçtikten sonra Mannheim\'da Ren\'e katılır.'),
  ('Almanya\'nın Bremen limanının kurulu olduğu ve Kuzey Denizi\'ne dökülen akarsu hangisidir?', 'Weser', ['Elbe', 'Ems', 'Spree Nehri'], 'Weser, Fulda ve Werra\'nın birleşmesiyle oluşur; Bremen\'den geçerek Bremerhaven yakınında Kuzey Denizi\'ne dökülür.'),
  ('Mozart\'ın doğduğu Salzburg kentinin içinden geçen akarsu hangisidir?', 'Salzach', ['Inn', 'Enns', 'Tuna'], 'Salzach, adını yörede yüzyıllardır taşınan tuzdan alır. Salzburg\'un eski kenti bu akarsuyun sol kıyısındadır.'),
  ('Münih\'in içinden geçen ve Alpler\'den doğarak Tuna\'ya katılan akarsu hangisidir?', 'Isar', ['Inn', 'Lech Nehri', 'Main'], 'Isar, Tirol\'deki Karwendel dağlarından doğar, Münih\'ten geçtikten sonra Deggendorf yakınında Tuna\'ya katılır.'),
  ('Volga\'dan sonra Avrupa\'nın en uzun ikinci akarsuyu hangisidir?', 'Tuna', ['Ren', 'Dinyeper', 'Ural'], 'Volga yaklaşık 3.530 km ile ilk sıradadır; Tuna yaklaşık 2.850 km ile ikinci gelir. Dinyeper yaklaşık 2.200 km, Ren ise 1.230 km dolayındadır.'),
  ('Hırvatistan\'ın başkenti Zagreb hangi akarsuyun kıyısındadır?', 'Sava', ['Drava', 'Neretva', 'Kupa'], 'Zagreb, Medvednica Dağı\'nın güney eteğinde, Sava Nehri\'nin kuzey kıyısında kurulmuştur.'),
  ('Lüksemburg kentinin eski şehri, Alzette ve Pétrusse akarsularının derin vadileri arasındaki kayalık bir platoya kurulmuştur. Bu konum tarihte kente en çok hangi avantajı sağlamıştır?', 'Doğal savunma', ['Kolay deniz ulaşımı', 'Verimli ova tarımı', 'Jeotermal enerji'], 'Derin vadilerle çevrili yüksek kaya, kenti \'Kuzeyin Cebelitarığı\' denen güçlü bir kale yapmıştır. Surları ve tünelleri UNESCO listesindedir.'),
  ('Amsterdam adını hangi akarsu üzerine kurulan setten alır?', 'Amstel', ['IJssel', 'Maas', 'Waal'], '13. yüzyılda Amstel Nehri üzerine bir set (dam) kurulmuş, kent bu setin çevresinde büyümüştür; ad \'Amstel\'deki set\' anlamındadır.'),
  ('İzlanda\'nın \'Altın Çember\' turistik rotasında yer alan, Hvítá Nehri\'nin iki basamakla derin bir kanyona döküldüğü şelale hangisidir?', 'Gullfoss', ['Dettifoss', 'Goðafoss', 'Svartifoss'], 'Gullfoss (\'Altın Şelale\'), Þingvellir ve Geysir ile birlikte Reykjavik yakınındaki Altın Çember\'in üç durağından biridir.'),
  ('İsviçre\'nin Bern Alpleri\'nde, dik duvarlarından Staubbach dahil onlarca şelalenin döküldüğü ünlü U biçimli vadi hangisidir?', 'Lauterbrunnen Vadisi', ['Engadin Vadisi', 'Ron Vadisi', 'Aosta Vadisi'], 'Lauterbrunnen, buzulların derinleştirdiği dik yamaçlı bir vadidir. Yan vadiler yüksekte kaldığından sular yüzlerce metre yükseklikten şelaleler hâlinde düşer.'),
  ('Avrupa anakarasının en büyük buzulu olarak bilinen Jostedalsbreen hangi ülkededir?', 'Norveç', ['İsveç', 'İsviçre', 'Avusturya'], 'Jostedalsbreen, Norveç\'in batısında Sognefjord\'un kuzeyinde uzanan geniş bir plato buzuludur. İzlanda ve Svalbard\'daki buzul örtüleri bunun dışında tutulur.'),
  ('Mont Blanc kütlesinin kuzey yamacından Chamonix vadisine doğru inen ve Fransa\'nın en uzun buzulu olan buzul hangisidir?', 'Mer de Glace', ['Aletsch Buzulu', 'Pasterze Buzulu', 'Ron Buzulu'], 'Mer de Glace (\'Buz Denizi\') yaklaşık 12 km uzunluğundadır. 19. yüzyıldan beri hızla geri çekilmesi Alp buzullarının erimesinin simgesi olmuştur.'),
  ('İsviçre\'deki Ren Şelalesi hangi kentin yakınındadır?', 'Schaffhausen', ['Basel', 'Bern', 'Lucerne'], 'Ren Şelalesi, Konstanz Gölü\'nden çıkan Ren\'in Schaffhausen yakınında yaklaşık 23 m düşmesiyle oluşur ve debi bakımından Orta Avrupa\'nın en büyük şelalesidir.'),
  ('Rusya Federasyonu\'nu oluşturan birimler arasında yüzölçümü en büyük olan, başkenti Yakutsk olan cumhuriyet hangisidir?', 'Saha', ['Tataristan', 'Başkurdistan', 'Karelya Cumhuriyeti'], 'Saha Cumhuriyeti yaklaşık 3 milyon km² ile Hindistan\'ın yüzölçümüne yaklaşan bir alana yayılır; ancak çok seyrek nüfusludur.'),
  ('Uzak Doğu\'daki Habarovsk kenti hangi iki akarsuyun birleştiği yere yakın kurulmuştur?', 'Amur ve Ussuri', ['Lena ve Aldan', 'Ob ve İrtiş', 'Yenisey ve Angara'], 'Habarovsk, Rusya-Çin sınırını izleyen Ussuri\'nin Amur\'a katıldığı noktanın hemen aşağısında, Amur\'un sağ kıyısındadır.'),
  ('Avrupa-Asya sınırı kabul edilen Ural Nehri\'nin kıyısında kurulduğu için iki kıtaya yayılan Rus kenti hangisidir?', 'Orenburg', ['Yekaterinburg', 'Perm', 'Tümen'], 'Orenburg, Ural Nehri\'nin iki yakasına yayılır. Nehrin sınır sayılması nedeniyle kentin bir kesimi Avrupa\'da, diğeri Asya\'da kalır.'),
  ('Güney Ural\'ın batı eteklerinde yer alan, başkenti Ufa olan ve adını bir Türk halkından alan Rus cumhuriyeti hangisidir?', 'Başkurdistan', ['Tataristan', 'Çuvaşistan', 'Udmurtya'], 'Başkurdistan, Belaya Nehri ve kolları boyunca Güney Ural\'a yayılır. Başkurtlar Türk dillerinin Kıpçak koluna ait bir dil konuşur.'),
  ('Rusya\'nın kuzeyindeki yerleşmelerin büyük çoğunluğunun kıyılarda ya da akarsu boylarında kurulmuş olmasının temel nedeni nedir?', 'Ulaşımın deniz ve akarsu yollarına bağlı olması', ['Bu alanların tümüyle verimli tarım toprakları olması', 'İç kesimlerde sürekli volkanik etkinlik bulunması', 'Kıyılarda permafrostun hiç bulunmaması'], 'Permafrost ve bataklıklar nedeniyle karayolu ve demiryolu yapımı çok zordur. Bu yüzden yazın akarsular, kışın ise donmuş akarsular üzerindeki buz yolları başlıca ulaşım yollarıdır.'),
  ('Sibirya\'da kışın donmuş akarsuların yüzeyinin araçlarla kullanılan geçici yollara dönüştürülmesine ne ad verilir?', 'Zimnik (buz yolu)', ['Kum dili', 'Polder yolu', 'Moren sırtı (esker)'], 'Zimnik denen kış yolları, akarsu ve bataklıkların donmasından sonra açılır. İlkbaharda buz çözülünce bu yollar kullanılamaz hâle gelir.'),
  ('Botni Körfezi\'nin kışları büyük ölçüde buzla kaplanmasında en etkili iki etken hangisidir?', 'Tuzluluğun düşük olması ve karasal soğuk hava', ['Suyun çok tuzlu olması ve Golf Akıntısı\'nın doğrudan etkisi', 'Körfezin ekvatora yakın olması ve yağışın çok az olması', 'Körfezde gelgit genliğinin okyanuslardan bile yüksek olması'], 'Akarsulardan gelen bol tatlı su körfezin tuzluluğunu düşürür; tuzu az olan su daha yüksek sıcaklıkta donar. Kışın İskandinavya ve Finlandiya üzerinden gelen çok soğuk hava da donmayı hızlandırır.'),
  ('Buzul Çağı\'nda deniz düzeyi düşükken Büyük Britanya\'yı kıta Avrupası\'na bağlayan ve bugün Kuzey Denizi\'nin altında kalan kara parçasına ne ad verilir?', 'Doggerland', ['Atlantis', 'Frizya', 'Lotharingia'], 'Son buzullaşmada deniz düzeyi bugünkünden çok daha düşüktü. Kuzey Denizi\'nin güneyi avcı-toplayıcıların yaşadığı bir ovaydı; buzullar eriyince bu kara sular altında kalmıştır.'),
  ('İtalya\'nın Lazio bölgesindeki Bolsena ve Bracciano gibi yuvarlak biçimli göllerin kökeni nedir?', 'Volkanik kaldera çöküntüleri', ['Buzulların oyduğu sirk çanakları', 'Karstik polye ve uvala çukurları', 'Tektonik graben (çöküntü) hendekleri'], 'Orta İtalya\'da Pleistosen\'de etkin olan volkanların magma odaları boşalınca kraterler çökerek kalderaları oluşturmuş, bunlar zamanla suyla dolmuştur.'),
  ('Fransa\'nın en uzun akarsuyu Loire nerede doğar?', 'Massif Central\'da', ['Alpler\'de', 'Pireneler\'de', 'Vosges Dağları\'nda'], 'Loire, Massif Central\'ın güneydoğusundaki Gerbier de Jonc Dağı\'nın eteğinden doğar; önce kuzeye, sonra batıya akarak Atlas\'a dökülür.'),
  ('Sicilya\'dan karayoluyla yola çıkıp İtalya Yarımadası boyunca kuzeye, Alpler\'e doğru giden bir gezgin aşağıdaki bölgelerden hangi sırayla geçer?', 'Kalabriya, Kampanya, Toskana, Lombardiya', ['Kampanya, Kalabriya, Lombardiya, Toskana', 'Toskana, Kalabriya, Kampanya, Lombardiya', 'Kalabriya, Toskana, Kampanya ve Lombardiya'], 'Kalabriya yarımadanın güney ucunda, Kampanya Napoli çevresinde, Toskana orta kesimde, Lombardiya ise kuzeyde Alpler\'in eteğindedir.'),
  ('Paris\'ten Marsilya\'ya giden hızlı tren Massif Central ile Alpler arasından geçer. Bu yolculuk büyük ölçüde hangi doğal koridoru izler?', 'Saône ve Ron vadilerini', ['Loire ve Garonne vadilerini', 'Ren ve Mosel vadilerini', 'Sen ve Somme vadilerini'], 'Saône-Ron oluğu Kuzey Fransa\'yı Akdeniz\'e bağlayan doğal bir geçittir. Lyon, iki akarsuyun birleştiği yerde bu koridorun ortasındadır.'),
  ('Alpler\'den doğup Verona\'dan geçen ve Po\'nun kuzeyinde Adriyatik\'e dökülen akarsu hangisidir?', 'Adige', ['Arno', 'Tiber', 'Piave'], 'Adige, İtalya\'nın ikinci uzun akarsuyudur. Güney Tirol\'den doğar, Trento ve Verona\'dan geçerek Venedik\'in güneyinde Adriyatik\'e ulaşır.'),
  ('Hollanda için sıkça kullanılan \'Holland\' adı aslında neyi anlatır?', 'Batıdaki Kuzey ve Güney Holland illerini', ['Ülkenin tamamını kapsayan anayasal ve resmî adı', 'Belçika ile paylaşılan tarihî bir sınır bölgesini', 'Ülkenin Karayipler\'deki denizaşırı adalarını'], 'Ülkenin resmî adı Nederland\'dır. Holland, Amsterdam ve Rotterdam\'ın bulunduğu, tarihte en güçlü olan iki batı ilinin ortak adıdır.'),
  ('Bir kentte ocak ortalaması yaklaşık 5 °C, temmuz ortalaması 15 °C\'dir ve yağış yılın her ayına dengeli dağılmıştır. Bu kent aşağıdakilerden hangisi olabilir?', 'Dublin', ['Moskova', 'Atina', 'Madrid'], 'Kışların ılık, yazların serin ve yağışın yıl boyu düzenli olması okyanus kıyısındaki Batı Avrupa kentlerine özgüdür. Moskova\'nın kışı çok soğuk, Atina ve Madrid\'in yazı ise sıcak ve kuraktır.'),
  ('Arhangelsk limanından yola çıkıp Murmansk\'a giden bir gemi sırasıyla hangi denizlerden geçer?', 'Beyaz Deniz, Barents Denizi', ['Baltık Denizi, Kuzey Denizi', 'Kara Denizi, Barents Denizi', 'Barents Denizi, Norveç Denizi'], 'Arhangelsk Beyaz Deniz\'in güney kıyısındadır. Gemi Beyaz Deniz\'den kuzeye çıkarak Barents Denizi\'ne açılır ve Kola Yarımadası\'nın kuzey kıyısındaki Murmansk\'a ulaşır.'),
  ('Bir öğrenci \'Kamçatka\'daki etkin volkanlar, Alpler gibi iki kıtanın birbirine çarpmasıyla oluşmuştur\' diyor. Bu ifade için hangisi doğrudur?', 'Yanlıştır; volkanlar okyanus levhasının dalmasıyla oluşur', ['Doğrudur; Asya ile Kuzey Amerika kıtaları burada çarpışır', 'Yanlıştır; Kamçatka\'da hiç etkin volkan bulunmaz', 'Doğrudur; volkanlar Alp kuşağının doğu ucunu oluşturur'], 'Kamçatka, Pasifik levhasının Okhotsk levhasının altına daldığı bir kuşağın üzerindedir. Dalan levhanın erimesiyle oluşan magma volkan zincirini besler; Alpler ise kıta-kıta çarpışmasıyla yükselmiştir.'),
  ('Güney İtalya\'da \'fiumara\' denen geniş çakıllı yatakların yazın çoğunlukla kuru kalıp kışın sel gibi akmasının nedeni nedir?', 'Yağışın kışa toplanıp yazın kuraklık olması', ['Bölgede yıl boyu düzenli ve bol yağış düşmesi', 'Akarsuların yazın eriyen Alp buzullarından beslenmesi', 'Yazın yer altı sularının yükselerek yüzeye taşması'], 'Akdeniz ikliminde yazlar kurak, kışlar yağışlıdır. Kısa ve dik yataklı akarsular yazın kurur, kış yağmurlarında ise ani ve güçlü akışa geçer.'),
  ('Ron Nehri\'nin Cenevre Gölü\'ne girmeden önceki yukarı çığırında akımın en yüksek olduğu mevsim hangisidir ve neden?', 'Yaz; buzul erimesi en yüksek düzeydedir', ['Kış; yağmurlar en fazla bu mevsimde düşer ve kar erimez', 'İlkbahar; alçak ovalardaki karlar bu dönemde erir', 'Sonbahar; Akdeniz fırtınaları akarsuyu güçlü biçimde besler'], 'Ron, Valais\'deki buzuldan doğar ve yukarı çığırında Alp buzullarıyla beslenir. Buzul erimesi temmuz-ağustosta en yüksek düzeye ulaştığından akım da yazın en fazladır.'),
  ('Amsterdam\'daki tarihî binaların çoğunun toprağa çakılmış uzun ahşap kazıklar üzerine yapılmasının nedeni nedir?', 'Zeminin yumuşak turba ve kilden oluşması', ['Kentin sık depremlere maruz kalması', 'Binaların sel sularının üzerinde yüzmesinin istenmesi', 'Kentin donmuş toprak üzerinde kurulmuş olması'], 'Amsterdam\'ın yüzey katmanları yumuşak ve suya doygundur. Kazıklar bu katmanları geçerek daha derindeki sağlam kum katmanına ulaşır ve binaların çökmesini önler.'),
  ('Fransa ile İspanya arasındaki ana karayolu ve demiryollarının Pireneler\'in ortasından değil, Atlas ve Akdeniz kıyılarına yakın uçlarından geçmesinin nedeni nedir?', 'Dağların orta kesiminin yüksek ve az geçitli olması', ['Kıyı kesimlerinin dağların ortasından daha yüksek olması', 'Orta kesimde büyük ve derin buzul göllerinin bulunması', 'Kıyı kesimlerinde hiçbir akarsu vadisinin bulunmaması'], 'Pireneler\'in orta kesimi 3.000 metreyi aşan zirveler ve az sayıda yüksek geçitle aşılması zor bir duvar oluşturur. Dağların denize alçaldığı iki uç ulaşım için çok daha elverişlidir.'),
  ('Baltık Denizi kıyılarında gelgitin neredeyse hiç hissedilmemesinin nedeni nedir?', 'Okyanusa dar boğazlarla bağlı kapalı bir deniz olması', ['Denizin ekvatora çok yakın bir enlemde yer alması', 'Baltık\'ın tuzluluğunun okyanus ortalamasından yüksek olması', 'Kıyılarının yüksek ve derin fiyortlarla çevrili olması'], 'Gelgit dalgası okyanustan Danimarka boğazları gibi dar geçitlerden Baltık\'a girerken büyük ölçüde söner. Bu yüzden Baltık\'ta gelgit genliği birkaç santimetreyi geçmez.'),
  ('Hazar Denizi\'nin Rusya kıyılarına yakın kuzey kesiminin suyu güney kesimine göre çok daha az tuzludur. Bunun başlıca nedeni nedir?', 'Volga ve Ural\'ın bol tatlı su getirmesi', ['Kuzey kesimde buharlaşmanın güneyden çok daha yüksek olması', 'Kuzey kesimin Baltık\'a ve okyanusa bir kanalla bağlanması', 'Güney kesime hiçbir akarsuyun dökülmemesi ve yağış olmaması'], 'Hazar\'a gelen tatlı suyun çoğunu kuzeyden dökülen Volga sağlar. Kuzey Hazar ayrıca çok sığdır; bu iki etken kuzeyin tuzluluğunu düşük tutar.'),
  ('Rusya\'nın Karadeniz kıyısındaki Novorossiysk limanının ülke için önemli olmasının coğrafi nedeni hangisidir?', 'Kışın buz tutmayan bir liman olması', ['Arktik Okyanusu\'na doğrudan açılan tek Rus limanı olması', 'Hazar Denizi kıyısındaki en derin ve en büyük liman olması', 'Baltık Denizi\'ne doğrudan bağlanan bir iç liman olması'], 'Rusya\'nın kuzey ve doğu kıyılarındaki limanların çoğu kışın buzla kaplanır. Novorossiysk ise yıl boyu açık kalan ve Akdeniz üzerinden dünya pazarlarına ulaşan önemli bir limandır.'),
  ('İsviçre gibi küçük bir ülkede dört ulusal dilin ve çok sayıda yerel lehçenin korunabilmesinde fiziki coğrafyanın payı nasıl açıklanabilir?', 'Dağlarla ayrılan vadilerin toplulukları yalıtması', ['Ülkenin geniş bir ovada yer alıp her yöne açık olması', 'Ülkenin uzun ve girintili bir deniz kıyısına sahip olması', 'Ülkenin tek bir büyük akarsu havzasından oluşması ve bütünleşmesi'], 'Alpler ve Jura, İsviçre\'yi birbirinden yüksek sırtlarla ayrılan vadilere böler. Yüzyıllar boyunca bu vadilerdeki topluluklar komşu dil bölgeleriyle bağlarını korurken kendi dillerini sürdürmüştür.'),
  ('Bir haritada Avrupa\'nın batı kıyıları ile doğusundaki Rusya kıyıları karşılaştırılıyor. Batı kıyılarının çok daha girintili çıkıntılı olması Avrupa\'nın batısı için hangi sonucu doğurmuştur?', 'Denizden uzak iç bölgelerin az olması, denizciliğin gelişmesi', ['Tarım alanlarının tamamen ortadan kalkıp ormanların yayılması', 'Akarsuların denize ulaşamayıp kapalı göllerde son bulması', 'İklimin doğuya göre çok daha karasal ve sert hâle gelmesi'], 'Batı Avrupa\'da yarımadalar, körfezler ve iç denizler kara içine sokulur. Böylece pek çok yer denize yakın kalmış, ticaret ve denizcilik erken dönemlerden itibaren gelişmiştir.'),
  ('Aşağıdaki akarsulardan hangisi Karadeniz havzasına aittir?', 'Dinyester', ['Vistül', 'Elbe', 'Loire'], 'Dinyester Ukrayna Karpatları\'ndan doğar, Moldova ile Ukrayna arasından geçerek Odessa\'nın güneybatısında Karadeniz\'e dökülür. Vistül Baltık\'a, Elbe Kuzey Denizi\'ne, Loire Atlas Okyanusu\'na akar.'),
  ('Aşağıdaki ülkelerden hangisi Polonya ile kara sınırı paylaşmaz?', 'Macaristan', ['Litvanya', 'Slovakya', 'Beyaz Rusya'], 'Polonya; Almanya, Çekya, Slovakya, Ukrayna, Beyaz Rusya, Litvanya ve Rusya\'nın Kaliningrad bölgesiyle komşudur. Macaristan ile Polonya arasında Slovakya bulunur.'),
  ('Finlandiya ve İzlanda \'Nordik ülkeler\' arasında sayılır ama dar anlamda \'İskandinav ülkeleri\' arasında genellikle sayılmaz. Dar anlamda İskandinav ülkeleri hangileridir?', 'Norveç, İsveç ve Danimarka', ['Norveç, İsveç ve Finlandiya', 'Danimarka, İzlanda ve Norveç', 'İsveç, Finlandiya ve Estonya'], 'İskandinavya dar anlamda dilleri birbirine yakın olan Norveç, İsveç ve Danimarka\'yı kapsar. Nordik ülkeler terimi bunlara Finlandiya ve İzlanda\'yı da ekler.'),
  ('Aşağıdaki kentlerden hangisi 60° kuzey enlemine diğerlerinden çok daha uzaktır?', 'Londra', ['Oslo', 'Helsinki', 'St. Petersburg'], 'Oslo, Helsinki ve St. Petersburg 60° kuzey enlemi çevresindedir. Londra ise yaklaşık 51,5° kuzeydedir ve bu çizgiden çok daha güneydedir.'),
  ('Malta\'nın içme suyunun önemli bir bölümünü deniz suyunu arıtarak sağlamasının coğrafi nedenleri hangisinde doğru verilmiştir?', 'Kalıcı akarsuyun olmaması ve yazların kurak geçmesi', ['Adanın kalın buzullarla kaplı olması ve suyun donması', 'Adada yağışın yıl boyu çok bol olup suyun taşması', 'Adadaki büyük göllerin tuzlu ve kirli olması'], 'Malta küçük ve alçak bir kireçtaşı adasıdır; yağış kısa kışa sıkışır ve kalıcı akarsu yoktur. Yer altı suyu sınırlı olduğu için tuzdan arındırma tesisleri önemli bir kaynaktır.'),
  ('Kuzey Norveç\'ten Sicilya\'ya karayoluyla giden bir gezgin doğal bitki örtüsünde kabaca hangi sırayla karşılaşır?', 'Tundra, iğne yapraklı orman, yaprak döken orman, maki', ['Maki, tundra, yaprak döken orman, iğne yapraklı orman', 'İğne yapraklı orman, tundra, maki, yaprak döken orman', 'Tundra, maki, iğne yapraklı orman ve yaprak döken orman'], 'Avrupa\'da kuzeyden güneye sıcaklık arttıkça Laponya tundrası yerini İskandinav taygasına, Orta Avrupa\'nın yaprak döken ormanlarına ve Akdeniz kıyılarının makilerine bırakır.'),
  ('Bir gezgin Akdeniz\'de volkanik bir adada yanardağ, Kuzey Atlas\'ta ise buzul ve gayzer görmek istiyor. Bu iki ziyaret için en uygun adalar hangi seçenekte doğru eşleştirilmiştir?', 'Sicilya ve İzlanda', ['Korsika ve İrlanda', 'Malta ve Shetland', 'Girit ve Gotland adası'], 'Sicilya\'da Etna, İzlanda\'da ise buzullar ile gayzerler bir aradadır. Korsika, Malta, Girit, İrlanda, Shetland ve Gotland\'da etkin volkan bulunmaz.'),
  ('Bir öğrenci \'Sibirya\'nın büyük ovası tümüyle tarım alanıdır\' diyor. Batı Sibirya Ovası için bu değerlendirme neden yanlıştır?', 'Ovanın çoğu bataklık, tayga ve tundradır', ['Ovanın tamamı yüksek ve sarp dağlarla örtülüdür', 'Ovanın tamamı sıcak kumul çölleriyle kaplıdır', 'Ovanın tamamı deniz düzeyinin altında, su altındadır'], 'Batı Sibirya Ovası düz olmasına karşın soğuk iklim, kötü drenaj ve permafrost nedeniyle büyük ölçüde bataklık ve ormanlıktır. Tarım yalnız güneydeki step kesiminde yaygındır.'),
  ('Trans-Sibirya Demiryolu ile Moskova\'dan Vladivostok\'a giden bir yolcu aşağıdaki kentlerden hangi sırayla geçer?', 'Yekaterinburg, Novosibirsk, Irkutsk', ['Novosibirsk, Yekaterinburg, Irkutsk', 'Irkutsk, Novosibirsk ve Yekaterinburg', 'Yekaterinburg, Irkutsk, Novosibirsk'], 'Hat önce Ural\'ı Yekaterinburg\'da aşar, ardından Ob kıyısındaki Novosibirsk\'e, daha doğuda ise Baykal\'ın batısındaki Irkutsk\'a ulaşır.'),
  ('St. Petersburg\'dan yük alan bir nehir gemisi denize çıkmadan Hazar Denizi\'ne ulaşmak istiyor. Hangi su yolunu izlemesi gerekir?', 'Volga-Baltık su yolundan Volga\'ya geçmek', ['Dinyeper üzerinden güneye inerek Karadeniz\'e çıkmak', 'Kuzey Dvina üzerinden kuzeye, Beyaz Deniz\'e çıkmak', 'Ob Nehri üzerinden kuzeye inip Kara Denizi\'ne ulaşmak'], 'Volga-Baltık su yolu, Neva, Ladoga, Svir ve Onega üzerinden kanallarla Volga\'ya bağlanır. Gemi oradan Volga boyunca güneye inerek Hazar\'a varır.'),
  ('Rusya\'nın en büyük hidroelektrik santrallerinin Avrupa kesiminden çok Sibirya\'daki Yenisey ve Angara üzerinde toplanmasının başlıca nedeni nedir?', 'Debilerinin yüksek, vadilerinin dar olması', ['Avrupa kesiminde hiçbir büyük akarsuyun bulunmaması', 'Sibirya\'da yazın hiç yağış düşmemesi ve suyun birikmesi', 'Bu akarsuların sıcak ve tuzlu güney denizlerine dökülmesi'], 'Yenisey ve Angara çok büyük su taşır; Angara ayrıca Baykal\'ın düzenli akışını alır. Platoyu yaran dar ve kayalık vadiler büyük barajlar kurmaya elverişlidir.'),
  ('Murmansk\'tan yola çıkıp Kuzey Deniz Yolu\'nu izleyerek Vladivostok\'a giden bir gemi Arktik\'ten Pasifik\'e geçerken hangi boğazı kullanır?', 'Bering Boğazı', ['Tatar Boğazı', 'Kerç Boğazı', 'La Pérouse Boğazı'], 'Kuzey Deniz Yolu Rusya\'nın Arktik kıyısını izler ve Çukotka ile Alaska arasındaki Bering Boğazı\'ndan Pasifik\'e çıkar.'),
  ('Rusya\'nın Kaliningrad bölgesindeki limanın, St. Petersburg\'a göre Baltık\'ta önemli bir üstünlüğü hangisidir?', 'Kışın genellikle buz tutmaması', ['Kuzey Denizi\'ne doğrudan ve geniş bir kıyısının olması', 'Arktik Okyanusu\'na açılan tek Rus limanı olması', 'Volga Nehri ile doğrudan kanal bağlantısının bulunması'], 'Fin Körfezi\'nin doğu ucundaki St. Petersburg kışın buz kırıcılara ihtiyaç duyar. Baltık\'ın güneydoğusundaki Kaliningrad limanı ise daha ılıman konumu nedeniyle büyük ölçüde açık kalır.'),
  ('Rusya\'nın Avrupa kesiminde, Moskova çevresindeki karışık ormanların güneyde yerini çayırlara bırakmasının temel iklim nedeni nedir?', 'Güneye doğru yağışın azalması', ['Güneye doğru sıcaklığın sürekli ve belirgin biçimde düşmesi', 'Güney kesimlerde yükseltinin 3.000 metreyi aşması', 'Güneye gidildikçe permafrost katmanının kalınlaşması'], 'Güneye inildikçe yazlar ısınır, buharlaşma artar ve yağış azalır. Toprak nemi ağaçları beslemeye yetmediğinde ormanın yerini step çayırları alır.'),
  ('Kamçatka ile Kuril Adaları\'nda deprem ve volkan etkinliğinin sık olmasına karşın Batı Sibirya Ovası\'nda bunların neredeyse hiç görülmemesi nasıl açıklanır?', 'Levha sınırlarından uzak, durağan bir alan olması', ['Batı Sibirya\'nın okyanus tabanında, su altında yer alması', 'Batı Sibirya\'nın Pasifik levhası üzerinde bulunması', 'Batı Sibirya\'nın genç ve yüksek kıvrım dağlarıyla kaplı olması'], 'Kamçatka ve Kuriller etkin bir dalma zonu üzerindedir. Batı Sibirya ise levhanın iç kesiminde kalın tortullarla örtülü durağan bir alandır.'),
  ('Aşağıdaki Avrupa ülkelerinden hangisinin Rusya ile ortak kara sınırı yoktur?', 'Romanya', ['Estonya', 'Letonya', 'Beyaz Rusya'], 'Rusya, Avrupa\'da Norveç, Finlandiya, Estonya, Letonya, Beyaz Rusya, Ukrayna ile ve Kaliningrad üzerinden Litvanya ile Polonya\'ya komşudur. Romanya ile Rusya arasında Ukrayna ve Moldova bulunur.'),
  ('Bir gezgin Avrupa haritasında \'çizmenin\' burnunun hemen ucunda, Messina Boğazı\'nın karşısında kalan büyük üçgen biçimli adayı gösteriyor. Bu adanın başkenti olan kent hangisidir?', 'Palermo', ['Cagliari', 'Napoli', 'Ajaccio'], 'Çizmeye benzeyen İtalya\'nın burnunun karşısındaki üçgen biçimli ada Sicilya\'dır; yönetim merkezi kuzey kıyısındaki Palermo\'dur. Cagliari Sardinya\'nın, Ajaccio Korsika\'nın merkezidir.'),
  ('Don Nehri hangi su kütlesine dökülür?', 'Azak Denizi', ['Hazar Denizi', 'Karadeniz\'in açık kesimine', 'Baltık Denizi'], 'Don Nehri Rusya\'da Taganrog Körfezi yoluyla Azak Denizi\'ne dökülür; Azak Karadeniz\'e Kerç Boğazı ile bağlıdır.'),
  ('Dünyanın en soğuk yerleşim yerlerinden biri sayılan ve kışın sıcaklığın çok düşmesiyle tanınan Oymyakon hangi Rus bölgesindedir?', 'Yakutistan (Saha) bölgesi', ['Karelya', 'Kamçatka Eyaleti', 'Tataristan'], 'Oymyakon, Yakutistan\'da yer alır; aşırı karasal iklim nedeniyle kışın sıcaklık -60 °C altına inebilir.'),
  ('Norilsk gibi kentler Rusya\'da hangi doğal kuşakta kurulduğu için ulaşım ve inşaat bakımından büyük zorluk yaşar?', 'Sürekli donmuş toprak (permafrost) kuşağında', ['Çernozem bozkırında', 'Orman-bozkır geçişinde', 'Subtropikal kıyı şeridinde'], 'Norilsk kutup dairesi ötesinde, permafrost üzerindedir; binaların kazıklar üzerine yapılması gerekir. Bölge nikel ve bakır madenciliğiyle bilinir.'),
  ('Norveç\'in kuzeybatı kıyısında, Lofoten ve Vesterålen olarak bilinen adalar hangi su kütlesinde yer alır?', 'Norveç Denizi', ['Baltık Denizi', 'Akdeniz', 'Ege Denizi'], 'Lofoten kutup çemberinin kuzeyinde olmasına rağmen Atlas\'tan gelen sıcak akıntı sayesinde ılıman kışlara sahiptir.'),
  ('Balkanlar\'da Yunanistan ve Bulgaristan\'ın sınır bölgesinde yer alan ve Orfeus efsanesiyle anılan dağ sırası hangisidir?', 'Rodop Dağları', ['Pindus Dağları', 'Ardenler', 'Tatra Dağları'], 'Rodoplar Bulgaristan ile Yunanistan arasında uzanır; Trakya\'nın batısında yer alır.'),
  ('Rodos ve Kos gibi adalar Yunanistan\'ın hangi takımadasına aittir?', 'Oniki Ada', ['Kiklad Adaları', 'İyon Adaları', 'Sporad Adaları'], 'Dodekanez Ege\'nin güneydoğusunda, Türkiye kıyılarına yakın uzanır. Santorini ise Kikladlar\'dandır.'),
  ('Balkan Yarımadası\'nın batı kıyısında Adriyatik\'e paralel uzanan dağ sırası hangisidir?', 'Dinar Alpleri', ['Rodoplar', 'Sudetler', 'Vosges'], 'Dinar Alpleri Slovenya\'dan Arnavutluk\'a dek kıyıya paralel uzanır ve karstik yer şekilleriyle tanınır.'),
  ('İsviçre\'de Cenevre Gölü\'nün kuzey kıyısında yer alan ve Uluslararası Olimpiyat Komitesi\'nin merkezi olan kent hangisidir?', 'Lozan', ['Bern', 'Cenevre', 'Zürih'], 'Lozan, Cenevre Gölü\'nün kuzey kıyısındadır. Zürih ise ülkenin en büyük kentidir.'),
  ('Belçika\'nın kuzey yarısında Flamanca, güney yarısında Fransızca konuşulur. Bu güney bölgenin adı nedir?', 'Valonya', ['Flandra', 'Brabant', 'Lüksemburg Eyaleti'], 'Valonya ülkenin güneyindeki Fransızca konuşan bölgedir; Flandra kuzeyde Flamanca konuşulan bölgedir.'),
  ('Beyaz Rusya ile Ukrayna arasında uzanan Pripet Bataklıkları\'nın oluşumunda hangi etken başlıca rol oynamıştır?', 'Düz arazide suyun akıp gidememesi ve yüksek taban suyu', ['Volkanik küllerin göllere dolması', 'Çöl rüzgârlarının getirdiği kum birikimi', 'Dağ buzullarının vadiyi oyması'], 'Pripet Havzası çok düşük eğimlidir; akarsular yavaş akar ve taban suyu yüzeye yakındır. Bu nedenle Avrupa\'nın en geniş bataklık alanlarından biri oluşmuştur.'),
  ('İtalya\'nın kuzeydoğusundaki Dolomitler\'i diğer Alp kesimlerinden ayıran, soluk renkli sarp kayalıkları oluşturan kayaç hangisidir?', 'Dolomit', ['Granit', 'Bazalt', 'Mermer'], 'Dolomitler adlarını kayaç türünden alır; magnezyumlu karbonat kayaçları açık renkli, dikey duvarlar ve sivri kuleler oluşturur.'),
  ('Almanya\'nın başkenti Berlin hangi akarsuların kıyısında yer alır?', 'Spree ve Havel', ['Elbe ve Saale', 'Ren ve Main', 'Weser ve Aller'], 'Berlin Brandenburg\'un ortasında, Spree\'nin Havel\'e katıldığı alandadır. Çevresi göllü ve düz bir morenlik düzlüktür.'),
  ('Büyük Britanya\'nın güneybatı ucunda denize uzanan ve Land\'s End burnuyla tanınan yarımada hangisidir?', 'Cornwall', ['Kent', 'Norfolk', 'Pembrokeshire'], 'Cornwall ada kıyısının güneybatı ucunu oluşturur; kıyı boyunca okyanusal iklim ve sert falezler görülür.'),
  ('Balkanlar\'ın en büyük gölü olan İşkodra (Skadar) Gölü hangi iki ülke arasında paylaşılır?', 'Karadağ ve Arnavutluk', ['Sırbistan ve Bosna-Hersek', 'Kuzey Makedonya ve Yunanistan', 'Hırvatistan ve Slovenya'], 'İşkodra Gölü karstik bir çanakta yer alır; kuzey bölümü Karadağ\'da, güney bölümü Arnavutluk\'tadır.'),
  ('Rostov-na-Donu kenti hangi akarsuyun kıyısında kurulmuştur?', 'Don', ['Volga', 'Kuban', 'Dinyeper'], 'Rostov-na-Donu adı \'Don üzerindeki Rostov\' anlamına gelir ve nehrin Azak Denizi\'ne yaklaştığı bölgede önemli bir ulaşım düğümüdür.'),
  ('Rusya\'da tayganın güneyinde başlayıp Ukrayna\'dan Altay\'a doğru uzanan geniş kuşakta doğal bitki örtüsünün ağaçsız otlaklardan oluşmasının temel nedeni nedir?', 'Yağışın buharlaşmayı karşılayamayacak kadar az olması', ['Toprağın sürekli donmuş olması', 'Kışların hiç soğuk geçmemesi', 'Aşırı yağış nedeniyle toprağın yıkanması'], 'Rus bozkırlarında yıllık yağış orman gelişimi için yetersizdir; ağaçlar yerine otsu bitkiler yaygındır ve altında verimli çernozem oluşur.'),
  ('Fransa\'nın ortasında yer alan, Auvergne\'deki eski yanardağlarla tanınan yüksek bölge hangisidir?', 'Merkezi Masif', ['Vosges', 'Jura', 'Ardenler'], 'Merkezi Masif, Fransa\'nın yaşlı ve volkanik yüksek platoluğudur; Loire ve Allier gibi akarsuların kaynak alanıdır.'),
  ('Ural\'ın doğu yamacında demir cevheri yataklarının hemen yanında kurulan ve çelik üretimiyle ünlenen Rus kenti hangisidir?', 'Magnitogorsk', ['Murmansk', 'Soçi', 'Kaliningrad'], 'Magnitogorsk, Magnitnaya Dağı\'ndaki zengin demir cevheri üzerine kurulmuştur ve Rusya\'nın büyük çelik merkezlerinden biridir.'),
  ('Batı Sibirya\'da Kemerovo çevresinde yer alan ve Rusya\'nın başlıca taşkömürü kaynağı olan havza hangisidir?', 'Kuznetsk Havzası', ['Donets Havzası', 'Ruhr Havzası', 'Pechora Havzası'], 'Kuznetsk Havzası Sibirya sanayisinin enerji ve çelik hammaddesi kaynağıdır; Ural çeliği ile birlikte demir-çelik ekseni oluşturmuştur.'),
  ('Airbus uçak üretim tesislerinin bulunduğu Toulouse hangi akarsuyun kıyısında yer alır?', 'Garonne', ['Loire', 'Seine', 'Dordogne'], 'Toulouse, güneybatı Fransa\'da Garonne kıyısındadır ve Avrupa havacılık sanayisinin önemli merkezlerindendir.'),
  ('İspanya\'nın Biskay Körfezi\'ne yakın Bask Bölgesi\'ndeki, demir cevheri ve çelik sanayisiyle gelişmiş büyük liman kenti hangisidir?', 'Bilbao', ['Sevilla', 'Cádiz', 'Zaragoza'], 'Bilbao Nervión Nehri kıyısında, çevresindeki demir cevheri yatakları sayesinde ağır sanayi merkezi olmuştur.'),
  ('İspanya\'nın Akdeniz kıyısındaki Valencia çevresinde narenciye ve pirinç tarımının yoğun olmasında en etkili etken hangisidir?', 'Sulanan verimli kıyı ovası ve Akdeniz iklimi', ['Sürekli kar örtüsü ve kısa yaz', 'Buzul çökelleri ve serin iklim', 'Dağlık ve engebeli arazi yapısı'], 'Valencia çevresinde \'huerta\' adı verilen sulu tarım alanları vardır; ılık kışlar ve uzun sıcak yazlar turunçgil ve pirinç yetiştirmeye elverir.'),
  ('Sırbistan\'ın kuzeyindeki verimli Pannonya Ovası\'nda yer alan ve merkezi Novi Sad olan özerk eyalet hangisidir?', 'Voyvodina', ['Kosova', 'Sancak', 'Banat Dağlığı'], 'Voyvodina Tuna ve Tisa\'nın sulattığı geniş bir ovadır; Sırbistan\'ın başlıca tahıl üretim bölgesidir.'),
  ('Mersey Nehri\'nin ağzında yer alan ve tarihte Atlantik ticaretiyle büyüyen İngiliz liman kenti hangisidir?', 'Liverpool', ['Hull', 'Southampton', 'Bristol'], 'Liverpool İrlanda Denizi\'ne açılır; Amerika kıtasıyla ticaret kapısı olarak sanayi devriminde hızla büyümüştür.'),
  ('Kuzey Denizi petrol ve doğal gaz endüstrisinin merkezi olan İskoçya\'nın doğu kıyısındaki liman kenti hangisidir?', 'Aberdeen', ['Edinburgh', 'Glasgow', 'Dundee'], 'Aberdeen 1970\'lerden itibaren Kuzey Denizi petrol sahalarının hizmet ve liman merkezi olmuştur.'),
  ('1949-1990 arasında Batı Almanya\'nın geçici başkenti olarak kullanılan ve Ren kıyısında bulunan kent hangisidir?', 'Bonn', ['Frankfurt', 'Köln', 'Düsseldorf'], 'Bonn Ren\'in kıyısındadır; Alman birleşmesine kadar Batı Almanya hükümet merkezi olmuştur.'),
  ('Bretanya Yarımadası\'nın batı ucunda yer alan ve Atlas Okyanusu\'na açılan Fransız liman kenti hangisidir?', 'Brest', ['Marsilya', 'Nice', 'Strazburg'], 'Brest Fransa\'nın en batısındaki limandır ve tarih boyunca Atlantik\'e açılan deniz üssü olarak önem taşımıştır.'),
  ('Loire Nehri\'nin ağzına yakın, Fransa\'nın batısında kurulu olan büyük liman kenti hangisidir?', 'Nantes', ['Toulouse', 'Lyon', 'Lille'], 'Nantes, Loire\'ın aşağı çığırında yer alır; nehrin Atlas Okyanusu\'na yaklaştığı kesimde ticaret ve sanayi merkezidir.'),
  ('Aşağıdaki kentlerden hangisi Ren kıyısında değildir?', 'Dresden', ['Düsseldorf', 'Bonn', 'Mainz'], 'Dresden Elbe Nehri\'nin kıyısındadır. Düsseldorf, Bonn ve Mainz Ren üzerinde yer alır.'),
  ('Leipzig ve Dresden kentleri hangi Alman eyaletinde yer alır?', 'Saksonya', ['Bavyera', 'Hessen', 'Brandenburg'], 'Leipzig ve Dresden, Almanya\'nın doğusunda Saksonya Eyaleti\'ndedir; Dresden Elbe kıyısındadır.'),
  ('İrlanda\'nın ikinci büyük kenti ve güneyde Lee Nehri\'nin kıyısında yer alan liman hangisidir?', 'Cork', ['Galway', 'Limerick', 'Belfast'], 'Cork Cumhuriyeti\'nin güneyinde, derin doğal limanı olan bir kenttir. Belfast ise Kuzey İrlanda\'dadır.'),
  ('Hollanda\'nın kuzeyindeki Groningen çevresinde çıkarılan başlıca fosil yakıt hangisidir?', 'Doğal gaz', ['Taşkömürü', 'Linyit', 'Ham petrol'], 'Groningen gaz sahası Avrupa\'nın büyük doğal gaz alanlarındandır ve Hollanda\'nın enerji ekonomisinde uzun süre belirleyici olmuştur.'),
  ('Mosel ve Ren vadilerinde yamaç bağcılığının yaygın olmasının nedeni nedir?', 'Güneye bakan yamaçların daha fazla güneş alması ve nehrin ısıyı düzenlemesi', ['Vadilerin sürekli buzla kaplı olması', 'Kıyıdaki tuzlu su baskınları', 'Çöl rüzgârlarının getirdiği sıcak hava'], 'Güneye bakan dik yamaçlar ışığı ve sıcağı daha iyi alır, nehirler de gece ısı kaybını azaltır; böylece serin kuşakta üzüm olgunlaşır.'),
  ('Slovenya\'daki Kras (Karst) Platosu\'nun adı dünya coğrafya literatürüne ne olarak geçmiştir?', 'Kireçtaşı bölgelerinde oluşan yer şekillerinin genel adı', ['Buzulların oyduğu vadi tipi', 'Volkanik kökenli ada türü', 'Rüzgârın oluşturduğu kumul türü'], 'Slovenya ve İtalya sınırındaki Kras bölgesi, kireçtaşının çözünmesiyle oluşan mağara ve düdenleriyle tanındığı için \'karst\' terimi dünyaca yayılmıştır.'),
];
